	(592, 'splitHandler', 'JB-QB-JBF-5009', '青鸟消防股份有限公司', 'JavaScript', 'channel', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decode(message) {\\n    var endTag = \\"0A 0A 0A 0A 0A\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    while (true) {\\n        var line = getLine(message, endTag);\\n        if (line.length > 0) {\\n            return line;\\n        }\\n\\n        message = message.substring(endTag.length);\\n        if (message.length == 0) {\\n            return \\"\\";\\n        }\\n    }\\n    return \\"\\";\\n}\\n\\nfunction getLine(message, endTag) {\\n    var line = getLine1(message, endTag);\\n    if (line.length > 0) {\\n        return line;\\n    }\\n\\n    line = getLine2(message, endTag);\\n    if (line.length > 0) {\\n        return line;\\n    }\\n\\n    line = getLine3(message, endTag);\\n    if (line.length > 0) {\\n        return line;\\n    }\\n\\n    return \\"\\";\\n}\\n\\n/**\\n * 范例1：\\n * 备电 故障\\n * 40/06/20 15:08:11\\n *\\n * 范例2：\\n * 感烟 故障\\n * 40/06/20 15:24:49 1001\\n *\\n * @param message\\n * @param endTag\\n */\\nfunction getLine1(message, endTag) {\\n    var end = indexOf(message, endTag, 0);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    var line = message.substring(0, end + endTag.length);\\n\\n    // 分拆行\\n    var lines = split(line, \\"0A\\");\\n    var items = removeEmpty(lines);\\n    if (items.length !== 2) {\\n        return \\"\\";\\n    }\\n\\n    // 40/06/20 15:08:11 或者 40/06/20 15:24:49 1001\\n    var dt = getAscii(items[1]).split(\\" \\");\\n    if (dt.length < 2) {\\n        return \\"\\";\\n    }\\n\\n    // 检查是否为日期格式\\n    var pattern = /^\\\\d{2}[/-]\\\\d{2}[/-]\\\\d{2}$/;\\n    if (!pattern.test(dt[0])) {\\n        return false;\\n    }\\n\\n    // 检测是否为时间格式\\n    pattern = /^\\\\d{2}\\\\:\\\\d{2}\\\\:\\\\d{2}$/;\\n    if (!pattern.test(dt[1])) {\\n        return false;\\n    }\\n\\n    // 检查，是否第一行末尾为告警类型，例如：备电 故障的HEX\\n    var typeTags = getTypeTag();\\n    for (var i = 0; i < typeTags.length; i++) {\\n        if (items[0].endsWith(typeTags[i])) {\\n            return line;\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n\\n/**\\n * 范例2：\\n * 手报\\n * 火警:40/06/20 15:13:34 1023\\n *\\n * @param message\\n * @param endTag\\n * @returns {string|boolean}\\n */\\nfunction getLine2(message, endTag) {\\n    var end = indexOf(message, endTag, 0);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    var line = message.substring(0, end + endTag.length);\\n\\n    // 分拆行\\n    var lines = split(line, \\"0A\\");\\n    var items = removeEmpty(lines);\\n    if (items.length !== 2) {\\n        return \\"\\";\\n    }\\n\\n    // 火警:40/06/20 15:13:34 1023\\n    var line2 = items[1];\\n    var start = indexOf(line2, \\"3A\\", 0);\\n    if (start < 2) {\\n        return \\"\\";\\n    }\\n    var type = line2.substring(0, start);\\n\\n    var dt = getAscii(line2.substring(start + 2)).split(\\" \\");\\n    if (dt.length !== 3) {\\n        return \\"\\";\\n    }\\n\\n    // 检查是否为日期格式\\n    var pattern = /^\\\\d{2}[/-]\\\\d{2}[/-]\\\\d{2}$/;\\n    if (!pattern.test(dt[0])) {\\n        return false;\\n    }\\n\\n    // 检测是否为时间格式\\n    pattern = /^\\\\d{2}\\\\:\\\\d{2}\\\\:\\\\d{2}$/;\\n    if (!pattern.test(dt[1])) {\\n        return false;\\n    }\\n\\n    // 检测是否为正整数\\n    pattern = /^\\\\d+$/;\\n    if (!pattern.test(dt[2])) {\\n        return false;\\n    }\\n\\n    // 检查，是否第一行末尾为告警类型，例如：备电 故障的HEX\\n    var typeTags = getTypeTag();\\n    for (var i = 0; i < typeTags.length; i++) {\\n        if (type == typeTags[i]) {\\n            return line;\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n\\n/**\\n * 范例3：\\n * 40/06/20 15:00:22 手动复位\\n * @param message\\n * @param endTag\\n */\\nfunction getLine3(message, endTag) {\\n    var end = indexOf(message, endTag, 0);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    var line = message.substring(0, end + endTag.length);\\n\\n    // 分拆行\\n    var lines = split(line, \\"0A\\");\\n    var items = removeEmpty(lines);\\n    if (items.length !== 1) {\\n        return \\"\\";\\n    }\\n\\n    // 40/06/20 15:00:22 手动复位\\n    items = split(items[0], \\"20\\");\\n    if (items.length !== 3) {\\n        return \\"\\";\\n    }\\n\\n    // 检查是否为日期格式\\n    var pattern = /^\\\\d{2}[/-]\\\\d{2}[/-]\\\\d{2}$/;\\n    if (!pattern.test(getAscii(items[0]))) {\\n        return false;\\n    }\\n\\n    // 检测是否为时间格式\\n    pattern = /^\\\\d{2}\\\\:\\\\d{2}\\\\:\\\\d{2}$/;\\n    if (!pattern.test(getAscii(items[1]))) {\\n        return false;\\n    }\\n\\n\\n    // 检查，是否第一行末尾为告警类型，例如：手动复位HEX\\n    var type = items[2];\\n    var typeTags = getTypeTag();\\n    for (var i = 0; i < typeTags.length; i++) {\\n        if (type.endsWith(typeTags[i])) {\\n            return line;\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n\\nfunction getTypeTag() {\\n    // GB2312的编码\\n    var tags = []\\n    // 故障\\n    tags.push(\\"B9CAD5CF\\");\\n    // 消音\\n    tags.push(\\"CFFBD2F4\\");\\n    //复位\\n    tags.push(\\"B8B4CEBB\\");\\n    //首警\\n    tags.push(\\"CAD7BEAF\\");\\n    // 火警\\n    tags.push(\\"BBF0BEAF\\");\\n    //启动\\n    tags.push(\\"C6F4B6AF\\");\\n    // 反馈\\n    tags.push(\\"B7B4C0A1\\");\\n\\n    return tags;\\n}\\n\\nfunction removeEmpty(lines) {\\n    var dats = [];\\n    for (var i = 0; i < lines.length; i++) {\\n        var line = lines[i].replace(/\\\\u0000/g, \'\');\\n        if (line.length == 0) {\\n            continue;\\n        }\\n\\n        dats.push(line);\\n    }\\n\\n    return dats;\\n}\\n\\nfunction split(hexStr, hexTag) {\\n    // 默认值处理\\n    if (hexStr == undefined) {\\n        return [];\\n    }\\n\\n    var hexs = \\"\\";\\n    for (var i = 0; i < hexStr.length; i++) {\\n        if (i % 2 == 0 && i !== 0) {\\n            hexs += \\" \\";\\n        }\\n        hexs += hexStr[i];\\n    }\\n\\n    var tags = \\"\\";\\n    for (var i = 0; i < hexTag.length; i++) {\\n        if (i % 2 == 0 && i !== 0) {\\n            tags += \\" \\";\\n        }\\n        tags += hexTag[i];\\n    }\\n\\n    var items = hexs.split(tags);\\n    for (var i = 0; i < items.length; i++) {\\n        items[i] = items[i].replaceAll(\\" \\", \\"\\");\\n    }\\n\\n\\n    return items;\\n}\\n\\n/**\\n * 查找特征位置\\n *\\n * @param hexStr\\n * @param hexTag\\n * @param position\\n * @returns {*|number|number}\\n */\\nfunction indexOf(hexStr, hexTag, position) {\\n    // 默认值处理\\n    if (position == undefined) {\\n        position = 0;\\n    }\\n\\n    if (position % 2 !== 0) {\\n        return -1;\\n    }\\n\\n    var pos = position;\\n    do {\\n        pos = hexStr.indexOf(hexTag, pos);\\n        if (pos < 0) {\\n            return -1;\\n        }\\n\\n        if (pos % 2 !== 0) {\\n            pos += 1;\\n            continue;\\n        }\\n\\n        return pos;\\n    } while (true);\\n}\\n\\nfunction getAscii(hexStr) {\\n    var text = \\"\\";\\n    for (var i = 0; i < hexStr.length; i += 2) {\\n        text += String.fromCharCode(parseInt(hexStr[i] + hexStr[i + 1], 16));\\n    }\\n\\n    return text;\\n}\\n", "main": "decode"}}', '{"description": "报文格式说明\\n1、数据有三种格式\\n2、格式1，单行，时间+类型，例如，40/06/20 15:00:22 手动复位\\n3、格式2，两行，类型+时间，例如，主电 故障\\\\0A40/06/20 15:06:17\\n4、格式3，两行，动作+类型+时间，例如，手报\\\\0A首警:40/06/20 15:12:44 1021\\n\\n\\n34 30 2F 30 36 2F 32 30 20 31 35 3A 30 30 3A 32 32 20 CA D6 B6 AF B8 B4 CE BB 0A 0A 0A 0A 0A \\n40/06/20 15:00:22 手动复位\\n\\n\\nD6 F7 B5 E7 20 B9 CA D5 CF 0A 34 30 2F 30 36 2F 32 30 20 31 35 3A 30 36 3A 31 37 0A 0A 0A 0A 0A\\n主电 故障\\n40/06/20 15:06:17\\n\\n\\nB1 B8 B5 E7 20 B9 CA D5 CF 0A 34 30 2F 30 36 2F 32 30 20 31 35 3A 30 38 3A 31 31 0A 0A 0A 0A 0A \\n备电 故障\\n40/06/20 15:08:11\\n\\n\\n34 30 2F 30 36 2F 32 30 20 31 35 3A 31 30 3A 32 35 20 CF FB D2 F4 0A 0A 0A 0A 0A\\n40/06/20 15:10:25 消音\\n\\n\\nCA D6 B1 A8 0A CA D7 BE AF 3A 34 30 2F 30 36 2F 32 30 20 31 35 3A 31 32 3A 34 34 20 31 30 32 31 0A 0A 0A 0A 0A\\n手报\\n首警:40/06/20 15:12:44 1021\\n\\n\\nCA D6 B1 A8 0A BB F0 BE AF 3A 34 30 2F 30 36 2F 32 30 20 31 35 3A 31 33 3A 33 34 20 31 30 32 33 0A 0A 0A 0A 0A \\n手报\\n火警:40/06/20 15:13:34 1023\\n\\n\\nCA D6 B1 A8 0A CA D7 BE AF 3A 34 30 2F 30 36 2F 32 30 20 31 35 3A 31 37 3A 32 38 20 31 30 32 31 0A CA D6 B1 A8 0A BB F0 BE AF 3A 34 30 2F 30 36 2F 32 30 20 31 35 3A 31 37 3A 32 38 20 31 30 32 33 0A 0A 0A 0A 0A \\n手报\\n首警:40/06/20 15:17:28 1021\\n手报\\n火警:40/06/20 15:17:28 1023\\n\\n\\nB8 D0 D1 CC 20 B9 CA D5 CF 0A 34 30 2F 30 36 2F 32 30 20 31 35 3A 32 34 3A 34 39 20 31 30 30 31 0A 0A 0A 0A 0A \\n感烟 故障\\n40/06/20 15:24:49 1001\\n\\n\\nCA E4 C8 EB CA E4 B3 F6 20 CA D6 B6 AF C6 F4 B6 AF 0A 34 30 2F 30 36 2F 32 30 20 31 35 3A 33 34 3A 31 31 20 31 30 32 38 0A 0A 0A 0A 0A \\n输入输出 手动启动\\n40/06/20 15:34:11 1028\\n\\n\\nB8 D0 D1 CC 20 B9 CA D5 CF 0A 34 30 2F 30 36 2F 32 30 20 31 35 3A 32 38 3A 33 39 20 31 30 30 37 0A  0A 0A 0A 0A \\n感烟 故障\\n40/06/20 15:28:39 1007\\n\\n"}', 'splitHandler', 'status', 1, 2000, 1727011531384, 1727011531384),
	(593, 'libs', 'JB-QB-JBF-5009', '青鸟消防股份有限公司', 'JavaScript', 'device', '{"include": {"code": "/**\\n * 按类型解码数据\\n *\\n * @param message 消息内容\\n * @param typeHeadTag 类型\\n * @returns {string|*[]} 数据\\n */\\nfunction decodeObj(message, lineCount) {\\n    var lines = message.split(\'\\\\n\');\\n\\n    var obj = {\\n        \\"data\\": [], \\"success\\": false, \\"message\\": \\"\\"\\n    }\\n\\n    // 剔除空行\\n    lines = removeEmpty(lines);\\n    if (lines.length < 1) {\\n        obj.message = \\"行数小于1\\";\\n        return obj;\\n    }\\n\\n    var dict = getDict();\\n\\n    var result = []\\n    while (lines.length > 0) {\\n        var record = {\\n            \\"device\\": \\"\\", \\"type\\": \\"\\", \\"date\\": \\"\\", \\"time\\": \\"\\", \\"oid\\": \\"\\", \\"success\\": false, \\"message\\": \\"\\"\\n        }\\n\\n        for (var i = 0; i < dict.length; i++) {\\n            var format = dict[i];\\n            record = getRecord(lines, format);\\n\\n            // 如果识别成功，剔除对应数量的尾行\\n            if (record.success) {\\n                for (var j = 0; j < format.length; j++) {\\n                    lines.pop();\\n                }\\n                break;\\n            }\\n        }\\n\\n        // 如果不成功：剔除这个无法识别的尾行\\n        if (!record.success) {\\n            lines.pop();\\n        } else {\\n            // 构造符合保持要求的格式：至少包含recordType\\n            var obj = {\\n                \\"recordType\\": record.type,\\n                \\"device\\": record.device,\\n                \\"date\\": record.date,\\n                \\"time\\": record.time,\\n                \\"oid\\": record.oid\\n            }\\n            result.push(obj);\\n        }\\n    }\\n\\n\\n    return result;\\n}\\n\\nfunction removeEmpty(lines) {\\n    var dats = [];\\n    for (var i = 0; i < lines.length; i++) {\\n        var line = lines[i].replace(/\\\\u0000/g, \'\');\\n        if (line.length == 0) {\\n            continue;\\n        }\\n\\n        dats.push(line);\\n    }\\n\\n    return dats;\\n}\\n\\nfunction getRecord(lines, format) {\\n    var record = {\\n        \\"device\\": \\"\\", \\"type\\": \\"\\", \\"date\\": \\"\\", \\"time\\": \\"\\", \\"oid\\": \\"\\", \\"success\\": false, \\"message\\": \\"\\"\\n    }\\n\\n    // 检查：长度是否足够\\n    if (lines.length < format.length) {\\n        record.message = \\"长度不足\\";\\n        return record;\\n    }\\n\\n    // 从尾部取出数据行\\n    var ls = [];\\n    for (var i = 0; i < lines.length; i++) {\\n        if (i < lines.length - format.length) {\\n            continue;\\n        }\\n\\n        ls.push(lines[i]);\\n    }\\n\\n    // 检查：格式是否匹配\\n    for (var i = 0; i < ls.length; i++) {\\n        var line = lines[i];\\n        var fmt = format[i];\\n\\n        // 检查：格式是否匹配\\n        if (!isFmt(line, fmt, record)) {\\n            record.message = \\"格式不匹配\\";\\n            return record;\\n        }\\n    }\\n\\n    record.success = true;\\n    return record;\\n}\\n\\nfunction isFmt(line, format, record) {\\n    var items = line.split(\\" \\");\\n\\n    if (items.length != format.length) {\\n        return false;\\n    }\\n\\n    for (var i = 0; i < format.length; i++) {\\n        var fmt = format[i];\\n        if (fmt === \\"device\\") {\\n            record.device = items[i];\\n            continue;\\n        }\\n        if (fmt === \\"type\\") {\\n            record.type = items[i];\\n            continue;\\n        }\\n        if (fmt === \\"type:date\\") {\\n            var its = items[i].split(\\":\\");\\n            if (its.length !== 2) {\\n                return false;\\n            }\\n\\n            record.type = its[0];\\n\\n            record.date = its[1];\\n\\n            var pattern = /^\\\\d{2}\\\\/\\\\d{2}\\\\/\\\\d{2}$/;\\n            if (!pattern.test(record.date)) {\\n                return false;\\n            }\\n            continue;\\n        }\\n        if (fmt === \\"date\\") {\\n            record.date = items[i];\\n\\n            var pattern = /^\\\\d{2}\\\\/\\\\d{2}\\\\/\\\\d{2}$/;\\n            if (!pattern.test(record.date)) {\\n                return false;\\n            }\\n            continue;\\n        }\\n        if (fmt === \\"time\\") {\\n            record.time = items[i];\\n\\n            var pattern = /^(\\\\d{2}):(\\\\d{2}):(\\\\d{2})$/;\\n            if (!pattern.test(record.time)) {\\n                return false;\\n            }\\n            continue;\\n        }\\n        if (fmt === \\"oid\\") {\\n            record.oid = items[i];\\n\\n            var pattern = /^-?\\\\d+(\\\\.\\\\d+)?$/;\\n            if (!pattern.test(record.oid)) {\\n                return false;\\n            }\\n\\n        }\\n    }\\n\\n    return true;\\n\\n}\\n\\nfunction getDict() {\\n    var dict = [];\\n\\n    // 感烟 故障\\n    // 40/06/20 15:28:39 1007\\n    dict.push([[\\"device\\", \\"type\\"], [\\"date\\", \\"time\\", \\"oid\\"]]);\\n\\n    // 40/06/20 15:00:22 手动复位\\n    dict.push([[\\"date\\", \\"time\\", \\"type\\"]]);\\n\\n    // 手报\\n    // 首警:40/06/20 15:12:44 1021\\n    dict.push([[\\"device\\"], [\\"type:date\\", \\"time\\", \\"oid\\"]]);\\n\\n    // 主电 故障\\n    // 40/06/20 15:06:17\\n    dict.push([[\\"device\\", \\"type\\"], [\\"date\\", \\"time\\"]]);\\n\\n\\n    return dict;\\n}", "main": "include"}}', '{"description": "报文格式：\\n【文本行1】【0A】\\n【文本行2】【0A】\\n【文本行3】【0A】\\n【文本行N】【0A】\\n\\n【0A 0A 0A 0A】\\n\\n范例1：\\nB8 D0 D1 CC 20 B9 CA D5 CF 0A \\n34 30 2F 30 36 2F 32 30 20 31 35 3A 32 38 3A 33 39 20 31 30 30 37 0A \\nB8 D0 D1 CC 20 B9 CA D5 CF 0A \\n34 30 2F 30 36 2F 32 30 20 31 35 3A 32 38 3A 33 39 20 31 30 30 38 0A\\n\\n3秒后，会发送0A 0A 0A 0A的结束报文\\n\\n解读：\\n感烟 故障\\n40/06/20 15:28:39 1007\\n感烟 故障\\n40/06/20 15:28:39 1008\\n\\n这是4行记录，2条告警。\\n注意：告警可能是1行，也可能是2行，有一定的格式\\n\\n注意：它的协议识别能力太弱，一台消防主机，必须独立占用一个串口。\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\nB8 D0 D1 CC 20 B9 CA D5 CF 0A 34 30 2F 30 36 2F 32 30 20 31 35 3A 32 38 3A 33 39 20 31 30 30 37 0A B8 D0 D1 CC 20 B9 CA D5 CF 0A 34 30 2F 30 36 2F 32 30 20 31 35 3A 32 38 3A 33 39 20 31 30 30 38 0A 0A 0A 0A 0A \\n\\n"}', 'include', 'record', 1, 2000, 1727011531397, 1727011531397),
	(594, '反馈', 'JB-TG-JBF-11S', '青鸟消防股份有限公司', 'JavaScript', 'device', '{"decode": {"code": "/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败:\\" + obj.message;\\n    }\\n\\n    var data = obj.data;\\n\\n    if (data.substring(0, 2) === \'04\') {\\n        var loop_addr = parseInt(data.substring(6, 8), 16);\\n        var node_addr = parseInt(data.substring(10, 12), 16);\\n\\n        var devAddr = loop_addr + \\"-\\" + node_addr;\\n\\n        var result = [];\\n\\n        var record = {\\n            \\"recordType\\": \\"反馈\\", \\"devAddr\\": devAddr\\n        };\\n\\n        result.push(record);\\n\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\n7E 01 02 02 02 01 00 5C FE 7E\\n\\n解读：\\n7E   报头 1字节\\n01 02 02  未知 3字节\\n02       长度 1字节\\n01 00  数据 N字节\\n5C FE  CRC-MODBUS\\n7E       报尾 1字节 \\n\\n其中数据的第1个字节为，上报类型代码\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n反馈（功能代码=04）\\n\\n15:11  10机2-146 输入模块动作\\n14#皮带喷淋进口阀\\n7E 01 02 02 1F 04 0A 00 02 00 92 00 09 15 07 14 0F 0B 28 31 34 23 C6 A4 B4 F8 C5 E7 C1 DC BD F8 BF DA B7 A7 61 AF 7E \\n"}', 'report', 'record', 1, 2000, 1727011533244, 1727011533244),
	(595, '调节主叫发送频率', 'JB-TG-JBF-11S', '青鸟消防股份有限公司', 'JavaScript', 'device', '{"encode": {"code": "/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction encode() {\\n    return encodeHex(fox_edge_param);\\n}\\n\\n/**\\n * 开发者自己写的编码函数1\\n * 返回格式1：HEX格式的字符串\\n *     比如串口通道，TCP通道、模拟通道，它们的输入/输出格式，就是HEX格式的文本\\n */\\nfunction encodeHex(param) {\\n    return \\"FF FF FF 09 00 00 01 6E 01 0A 00 03\\";\\n}\\n", "main": "encode"}}', '{"description": "设备信息的上报，先要定期发出主叫操作，周期性的激活与设备的连接\\n\\n调节主叫发送频率"}', 'publish', 'status', 1, 2000, 1727011533260, 1727011533260),
	(596, 'splitHandler', 'JB-TG-JBF-11S', '青鸟消防股份有限公司', 'JavaScript', 'channel', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decode(message) {\\n    var starTag = \\"7E\\";\\n    var endTag = \\"7E\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    // 找到起始符\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 切掉前面的数据\\n    message = message.substring(start);\\n\\n    while (true) {\\n        // 切出第一行\\n        var line = getLine(message, starTag, endTag);\\n        if (line.length > 0) {\\n            return line;\\n        }\\n\\n        message = message.substring(start + starTag.length);\\n        if (message.length == 0) {\\n            return \\"\\";\\n        }\\n    }\\n\\n\\n    return \\"\\";\\n}\\n\\n\\nfunction getData(line) {\\n    return line.substring(10, line.length - 6);\\n}\\n\\n/**\\n * 分拆行\\n * @param message 消息\\n * @param starTag 起始符\\n * @param endTag 结束符\\n * @returns {string} 行\\n */\\nfunction getLine(message, starTag, endTag) {\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start !== 0) {\\n        return \\"\\";\\n    }\\n\\n    // 检测：最小长度\\n    if (message.length < 16) {\\n        return \\"\\";\\n    }\\n\\n    // 数据大小\\n    var size = parseInt(message.substring(8, 10), 16);\\n\\n    // 切第一行\\n    var line = message.substring(start, start + 16 + size * 2);\\n    if (line.substring(line.length - endTag.length, line.length) !== endTag) {\\n        return \\"\\";\\n    }\\n\\n    // 截取第一行，并进行行验证\\n    if (!verifyLine(line)) {\\n        return \\"\\";\\n    }\\n\\n    return line;\\n}\\n\\n/**\\n * 验证CRC\\n *\\n * @param line 行信息\\n * @returns {boolean} 是否成功\\n */\\nfunction verifyLine(line) {\\n    if (line.length < 16) {\\n        return false;\\n    }\\n\\n    var body = line.substring(0, line.length - 6);\\n\\n    // 校验帧长度\\n    var size = parseInt(line.substring(8, 10), 16);\\n    if (line.length != 16 + size * 2) {\\n        return false;\\n    }\\n\\n\\n    var ch = line.substring(line.length - 4, line.length - 2);\\n    var cl = line.substring(line.length - 6, line.length - 4);\\n    var crc = calculateCRC16(body, 0xFFFF, 0xA001);\\n\\n    return crc === ch + cl;\\n}\\n\\n/**\\n * CRC16校验\\n * 范例：calculateCRC16(\\"7E0000000133000100\\", 0x0000, 0xA001);\\n *\\n * @param dataHexString 无空格的HEX格式文本，例如：\\"7E0000000133000100\\";\\n * @param init CRC16的初始值，例如：0x0000\\n * @param poly CRC16的多项式，例如：0xA001\\n * @returns {string}\\n */\\nfunction calculateCRC16(dataHexString, init, poly) {\\n    var dataBytes = [];\\n    for (var i = 0; i < dataHexString.length; i += 2) {\\n        dataBytes.push(parseInt(dataHexString.substring(i, i + 2), 16));\\n    }\\n\\n    var crc = init;\\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\\n\\n    for (var i = 0; i < dataBytes.length; i++) {\\n        crc ^= dataBytes[i];\\n        for (var j = 0; j < 8; j++) {\\n            if (crc & 0x0001) {\\n                crc = ((crc >> 1) ^ polynomial) & 0xFFFF;\\n            } else {\\n                crc >>= 1;\\n            }\\n        }\\n    }\\n\\n    crc = crc & 0xffff\\n\\n    var txt = crc.toString(16).toUpperCase();\\n    txt = padStart(txt, 4, \'0\');\\n    return txt;\\n}\\n\\nfunction padStart(str, length, ch) {\\n    while (str.length < length) {\\n        str = ch + str;\\n    }\\n\\n    return str;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\n7E 01 02 02 02 01 00 5C FE 7E\\n\\n解读：\\n7E   报头 1字节\\n01 02 02  未知 3字节\\n02       长度 1字节\\n01 00  数据 N字节\\n5C FE  CRC-MODBUS\\n7E       报尾 1字节 \\n\\n其中数据的第1个字节为，上报类型代码\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n7E 01 02 02 02 01 00 5C FE 7E\\n\\n测试报文2：\\n7E 01 02 02 09   96 01 00 15 07 14 10 07 13 43 09 7E \\n\\n"}', 'splitHandler', 'status', 1, 2000, 1727011533274, 1727011533274),
	(597, '火警', 'JB-TG-JBF-11S', '青鸟消防股份有限公司', 'JavaScript', 'device', '{"decode": {"code": "/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败:\\" + obj.message;\\n    }\\n\\n    var data = obj.data;\\n\\n    if (data.substring(0, 2) === \'02\') {\\n        var loop_addr = parseInt(data.substring(6, 8), 16);\\n        var node_addr = parseInt(data.substring(10, 12), 16);\\n\\n        var devAddr = loop_addr + \\"-\\" + node_addr;\\n\\n        var result = [];\\n\\n        var record = {\\n            \\"recordType\\": \\"火警\\", \\"devAddr\\": devAddr\\n        };\\n\\n        result.push(record);\\n\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\n7E 01 02 02 02 01 00 5C FE 7E\\n\\n解读：\\n7E   报头 1字节\\n01 02 02  未知 3字节\\n02       长度 1字节\\n01 00  数据 N字节\\n5C FE  CRC-MODBUS\\n7E       报尾 1字节 \\n\\n其中数据的第1个字节为，上报类型代码\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n复位（功能代码=02）\\n\\n16:26:40   3机1-66 手报火警 \\n152中控室西南前隔离室手报\\n7E 01 02 02 27 02 03 00 01 00 42 00 01 15 07 14 10 1A 28 31 35 32 D6 D0 BF D8 CA D2 CE F7 C4 CF C7 B0 B8 F4 C0 EB CA D2 CA D6 B1 A8 41 8A 7E\\n"}', 'report', 'record', 1, 2000, 1727011533286, 1727011533286),
	(598, '多线无反馈', 'JB-TG-JBF-11S', '青鸟消防股份有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败:\\" + obj.message;\\n    }\\n\\n    var data = obj.data;\\n\\n    if (data.substring(0, 2) === \'82\') {\\n        var loop_addr = parseInt(data.substring(6, 8), 16);\\n        var node_addr = parseInt(data.substring(10, 12), 16);\\n\\n        var devAddr = loop_addr + \\"-\\" + node_addr;\\n\\n        var result = [];\\n\\n        var record = {\\n            \\"recordType\\": \\"多线无反馈\\"\\n        };\\n\\n        result.push(record);\\n\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}\\n", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\n7E 01 02 02 02 01 00 5C FE 7E\\n\\n解读：\\n7E   报头 1字节\\n01 02 02  未知 3字节\\n02       长度 1字节\\n01 00  数据 N字节\\n5C FE  CRC-MODBUS\\n7E       报尾 1字节 \\n\\n其中数据的第1个字节为，上报类型代码\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n多线无反馈（功能代码=82）\\n\\n"}', 'report', 'status', 1, 2000, 1727011533298, 1727011533298),
	(599, '多线手动直启', 'JB-TG-JBF-11S', '青鸟消防股份有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败:\\" + obj.message;\\n    }\\n\\n    var data = obj.data;\\n\\n    if (data.substring(0, 2) === \'03\') {\\n        var loop_addr = parseInt(data.substring(6, 8), 16);\\n        var node_addr = parseInt(data.substring(10, 12), 16);\\n\\n        var devAddr = loop_addr + \\"-\\" + node_addr;\\n\\n        var result = [];\\n\\n        var record = {\\n            \\"recordType\\": \\"多线手动直启\\"\\n        };\\n\\n        result.push(record);\\n\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}\\n", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\n7E 01 02 02 02 01 00 5C FE 7E\\n\\n解读：\\n7E   报头 1字节\\n01 02 02  未知 3字节\\n02       长度 1字节\\n01 00  数据 N字节\\n5C FE  CRC-MODBUS\\n7E       报尾 1字节 \\n\\n其中数据的第1个字节为，上报类型代码\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n多线手动直启（功能代码=03）\\n\\n"}', 'report', 'record', 1, 2000, 1727011533310, 1727011533310),
