t(data.substring(2, 4), 16) * 0x100;\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        var record = {\\n            \\"recordType\\": \\"启动清零\\"\\n        };\\n\\n        result.push(record);\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n启动清零\\nFE 01 70 02 00 00 00 41 B9 FF"}', 'report', 'record', 1, 2000, 1727011534462, 1727011534462),
	(612, '启动', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败\\";\\n    }\\n\\n    if (obj.type === \'70\' && obj.data.length >= 68) {\\n        var data = obj.data;\\n\\n        // 校验帧长度\\n        var count = parseInt(data.substring(0, 2), 16);\\n        count += parseInt(data.substring(2, 4), 16) * 0x100;\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        for (var i = 0; i < count; i++) {\\n            var host_addr = parseInt(data.substring(64 * i + 4, 64 * i + 6), 16);\\n            var loop_addr = parseInt(data.substring(64 * i + 6, 64 * i + 8), 16);\\n            var node_addr = parseInt(data.substring(64 * i + 8, 64 * i + 10), 16);\\n\\n            var devAddr = host_addr + \\"-\\" + loop_addr + \\"-\\" + node_addr;\\n            var text = \\"(\\" + host_addr + \\"号分机) \\" + loop_addr + \\"-\\" + node_addr;\\n            var record = {\\n                \\"recordType\\": \\"启动\\", \\"devAddr\\": devAddr, \\"text\\": text\\n            };\\n\\n            result.push(record);\\n        }\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n1号机 单元1 分区1 气体灭火声光启动\\nFE 01 70 22 00 01 00 01 01 01 01 00 16 07 19 10 23 12 57 FF FF 28 0B 35 1E 37 10 36 23 18 46 1E 0F FF FF FF FF FF FF D2 82 FF\\n\\n"}', 'report', 'record', 1, 2000, 1727011534473, 1727011534473),
	(613, 'splitHandler', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'channel', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decode(message) {\\n    var starTag = \\"FE\\";\\n    var endTag = \\"FF\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    // 找到起始符\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    while (true) {\\n        var line = getNext(message, starTag, endTag);\\n        if (line.length > 0) {\\n            return line;\\n        }\\n\\n        message = message.substring(endTag.length);\\n        if (message.length == 0) {\\n            return \\"\\";\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n\\nfunction getNext(message, starTag, endTag) {\\n    // 找到起始符\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 切掉前面的数据\\n    message = message.substring(start);\\n\\n    // 切出第一行\\n    var line = getLine(message, starTag, endTag);\\n    if (line.length === 0) {\\n        return \\"\\";\\n    }\\n\\n    //取出行信息\\n    var type = getType(line);\\n    var data = getData(line);\\n\\n    var entity = {\\n        \\"type\\": type, \\"data\\": data\\n    }\\n\\n    return line;\\n}\\n\\n\\n/**\\n * 从行中取出帧类型\\n *\\n * @param line 行信息\\n * @returns {string} 帧类型，例如：64\\n */\\nfunction getType(line) {\\n    return line.substring(4, 6);\\n}\\n\\nfunction getData(line) {\\n    return line.substring(10, line.length - 6);\\n}\\n\\n/**\\n * 分拆行\\n * @param message 消息\\n * @param starTag 起始符\\n * @param endTag 结束符\\n * @returns {string} 行\\n */\\nfunction getLine(message, starTag, endTag) {\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start !== 0) {\\n        return \\"\\";\\n    }\\n\\n    // 检测：最小长度\\n    if (message.length < 16) {\\n        return \\"\\";\\n    }\\n\\n    // 数据大小\\n    var size = parseInt(message.substring(6, 8), 16);\\n    size += parseInt(message.substring(8, 10), 16) * 0x100;\\n\\n    // 切第一行\\n    var line = message.substring(start, start + 16 + size * 2);\\n    if (line.substring(line.length - endTag.length, line.length) !== endTag) {\\n        return \\"\\";\\n    }\\n\\n    // 截取第一行，并进行行验证\\n    if (!verifyLine(line)) {\\n        return \\"\\";\\n    }\\n\\n    return line;\\n}\\n\\n/**\\n * 验证CRC\\n *\\n * @param line 行信息\\n * @returns {boolean} 是否成功\\n */\\nfunction verifyLine(line) {\\n    if (line.length < 16) {\\n        return false;\\n    }\\n\\n    var body = line.substring(2, line.length - 6);\\n\\n    // 校验帧长度\\n    var size = parseInt(line.substring(6, 8), 16);\\n    size += parseInt(line.substring(8, 10), 16) * 0x100;\\n    if (line.length != 16 + size * 2) {\\n        return false;\\n    }\\n\\n\\n    var ch = line.substring(line.length - 4, line.length - 2);\\n    var cl = line.substring(line.length - 6, line.length - 4);\\n    var crc = calculateCRC16(body, 0xFFFF, 0xA001);\\n\\n    return crc === ch + cl;\\n}\\n\\n/**\\n * CRC16校验\\n * 范例：calculateCRC16(\\"7E0000000133000100\\", 0x0000, 0xA001);\\n *\\n * @param dataHexString 无空格的HEX格式文本，例如：\\"7E0000000133000100\\";\\n * @param init CRC16的初始值，例如：0x0000\\n * @param poly CRC16的多项式，例如：0xA001\\n * @returns {string}\\n */\\nfunction calculateCRC16(dataHexString, init, poly) {\\n    var dataBytes = [];\\n    for (var i = 0; i < dataHexString.length; i += 2) {\\n        dataBytes.push(parseInt(dataHexString.substring(i, i + 2), 16));\\n    }\\n\\n    var crc = init;\\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\\n\\n    for (var i = 0; i < dataBytes.length; i++) {\\n        crc ^= dataBytes[i];\\n        for (var j = 0; j < 8; j++) {\\n            if (crc & 0x0001) {\\n                crc = ((crc >> 1) ^ polynomial) & 0xFFFF;\\n            } else {\\n                crc >>= 1;\\n            }\\n        }\\n    }\\n\\n    crc = crc & 0xffff\\n\\n    var txt = crc.toString(16).toUpperCase();\\n    txt = padStart(txt, 4, \'0\');\\n    return txt;\\n}\\n\\nfunction padStart(str, length, ch) {\\n    while (str.length < length) {\\n        str = ch + str;\\n    }\\n\\n    return str;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\nFE 01 6E 22 00 01 00 01 01 03 02 00 09 01 19 12 31 12 35 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 68 7B FF \\n\\n测试报文2：\\nFE 01 00 01 00 00 48 00 FF\\n\\n测试报文3：\\nFE 01 64 01 00 64 56 DB FF\\n\\n"}', 'splitHandler', 'status', 1, 2000, 1727011534484, 1729172383979),
	(614, '屏蔽', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败\\";\\n    }\\n\\n    if (obj.type === \'73\' && obj.data.length >= 68) {\\n        var data = obj.data;\\n\\n        // 校验帧长度\\n        var count = parseInt(data.substring(0, 2), 16);\\n        count += parseInt(data.substring(2, 4), 16) * 0x100;\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        for (var i = 0; i < count; i++) {\\n            var host_addr = parseInt(data.substring(64 * i + 4, 64 * i + 6), 16);\\n            var loop_addr = parseInt(data.substring(64 * i + 6, 64 * i + 8), 16);\\n            var node_addr = parseInt(data.substring(64 * i + 8, 64 * i + 10), 16);\\n\\n            var devAddr = host_addr + \\"-\\" + loop_addr + \\"-\\" + node_addr;\\n            var text = \\"(\\" + host_addr + \\"号分机) \\" + loop_addr + \\"-\\" + node_addr;\\n            var record = {\\n                \\"recordType\\": \\"屏蔽\\", \\"devAddr\\": devAddr, \\"text\\": text\\n            };\\n\\n            result.push(record);\\n        }\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "类型代码：0x73\\n\\n机号1 屏蔽 回路1点号122 分区3 \\nFE 01 73 22 00 01 00 01 01 7A 03 A0 00 03 20 07 02 14 04 03 22 27 58 32 1B 12 43 1B 59 11 1E 2A 49 1F 42 FF FF FF FF 6A C3 FF"}', 'report', 'record', 1, 2000, 1727011534495, 1727011534495),
	(615, '火警', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败\\";\\n    }\\n\\n    if (obj.type === \'6E\' && obj.data.length >= 68) {\\n        var data = obj.data;\\n\\n        // 校验帧长度\\n        var count = parseInt(data.substring(0, 2), 16);\\n        count += parseInt(data.substring(2, 4), 16) * 0x100;\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        for (var i = 0; i < count; i++) {\\n            var host_addr = parseInt(data.substring(64 * i + 4, 64 * i + 6), 16);\\n            var loop_addr = parseInt(data.substring(64 * i + 6, 64 * i + 8), 16);\\n            var node_addr = parseInt(data.substring(64 * i + 8, 64 * i + 10), 16);\\n\\n            var devAddr = host_addr + \\"-\\" + loop_addr + \\"-\\" + node_addr;\\n            var text = \\"(\\" + host_addr + \\"号分机) \\" + loop_addr + \\"-\\" + node_addr;\\n            var record = {\\n                \\"recordType\\": \\"火警\\", \\"devAddr\\": devAddr, \\"text\\": text\\n            };\\n\\n            result.push(record);\\n        }\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}\\n", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n1个火警：（1号机）1-3红外光束2分区，\\n\\nFE 01 6E 22 00 01 00 01 01 03 02 00 09 01 19 12 31 12 35 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 68 7B FF \\n\\n"}', 'report', 'record', 1, 2000, 1727011534509, 1727011534509),
	(616, '故障恢复', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败\\";\\n    }\\n\\n    if (obj.type === \'6F\' && obj.data.length === 4) {\\n        var data = obj.data;\\n\\n        // 校验帧长度\\n        var count = parseInt(data.substring(0, 2), 16);\\n        count += parseInt(data.substring(2, 4), 16) * 0x100;\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        var record = {\\n            \\"recordType\\": \\"故障恢复\\"\\n        };\\n\\n        result.push(record);\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n故障恢复：（全部恢复）\\nFE 01 6F 02 00 00 00 D4 7B FF     "}', 'report', 'record', 1, 2000, 1727011534521, 1727011534521),
	(617, '复位', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败\\";\\n    }\\n\\n    // 心跳包\\n    if (obj.type === \'00\') {\\n        var data = obj.data;\\n\\n        // 校验帧长度\\n        var count = parseInt(data.substring(0, 2), 16);\\n        count += parseInt(data.substring(2, 4), 16) * 0x100;\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        var record = {\\n            \\"recordType\\": \\"复位\\"\\n        };\\n\\n        result.push(record);\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n测试报文：\\nFE 01 00 01 00 00 48 00 FF\\n"}', 'report', 'record', 1, 2000, 1727011534531, 1727011534531),
	(618, '故障', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败\\";\\n    }\\n\\n    if (obj.type === \'6F\' && obj.data.length >= 68) {\\n        var data = obj.data;\\n\\n        // 校验帧长度\\n        var count = parseInt(data.substring(0, 2), 16);\\n        count += parseInt(data.substring(2, 4), 16) * 0x100;\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        for (var i = 0; i < count; i++) {\\n            var host_addr = parseInt(data.substring(64 * i + 4, 64 * i + 6), 16);\\n            var loop_addr = parseInt(data.substring(64 * i + 6, 64 * i + 8), 16);\\n            var node_addr = parseInt(data.substring(64 * i + 8, 64 * i + 10), 16);\\n\\n            var devAddr = host_addr + \\"-\\" + loop_addr + \\"-\\" + node_addr;\\n            var text = \\"(\\" + host_addr + \\"号分机) \\" + loop_addr + \\"-\\" + node_addr;\\n            var record = {\\n                \\"recordType\\": \\"故障\\", \\"devAddr\\": devAddr, \\"text\\": text\\n            };\\n\\n            result.push(record);\\n        }\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n故障恢复：（全部恢复）\\nFE 01 6F 02 00 00 00 D4 7B FF         \\n\\n\\n5个故障：（1号机）1-16感温3分区 ，1-17感温3分区， 1-18感温3分区 ，1-19感温3分区， 1-20感温3分区 \\nFE 01 6F A2 00 05 00 01 01 10 03 00 01 08 19 12 31 12 17 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 01 01 11 03 00 01 08 19 12 31 12 17 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 01 01 12 03 00 01 08 19 12 31 12 17 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 01 01 13 03 00 01 08 19 12 31 12 17 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 01 01 14 03 00 01 08 19 12 31 12 17 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 84 42 FF \\n\\n"}', 'report', 'record', 1, 2000, 1727011534542, 1727011534542),
	(619, 'libs', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"include": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decodeObj(message) {\\n    var starTag = \\"FE\\";\\n    var endTag = \\"FF\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    var obj = {\\n        \\"type\\": type, \\"data\\": data, \\"success\\": false\\n    }\\n\\n    // 找到起始符\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return obj;\\n    }\\n\\n    // 切掉前面的数据\\n    message = message.substring(start);\\n\\n    // 切出第一行\\n    var line = getLine(message, starTag, endTag);\\n    if (line.length === 0) {\\n        return obj;\\n    }\\n\\n    //取出行信息\\n    var type = getType(line);\\n    var data = getData(line);\\n\\n    obj = {\\n        \\"type\\": type, \\"data\\": data, \\"success\\": true\\n    }\\n\\n    return obj;\\n}\\n\\n\\n/**\\n * 从行中取出帧类型\\n *\\n * @param line 行信息\\n * @returns {string} 帧类型，例如：64\\n */\\nfunction getType(line) {\\n    return line.substring(4, 6);\\n}\\n\\nfunction getData(line) {\\n    return line.substring(10, line.length - 6);\\n}\\n\\n/**\\n * 分拆行\\n * @param message 消息\\n * @param starTag 起始符\\n * @param endTag 结束符\\n * @returns {string} 行\\n */\\nfunction getLine(message, starTag, endTag) {\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start !== 0) {\\n        return \\"\\";\\n    }\\n\\n    // 检测：最小长度\\n    if (message.length < 16) {\\n        return \\"\\";\\n    }\\n\\n    // 数据大小\\n    var size = parseInt(message.substring(6, 8), 16);\\n    size += parseInt(message.substring(8, 10), 16) * 0x100;\\n\\n    // 切第一行\\n    var line = message.substring(start, start + 16 + size * 2);\\n    if (line.substring(line.length - endTag.length, line.length) !== endTag) {\\n        return \\"\\";\\n    }\\n\\n    // 截取第一行，并进行行验证\\n    if (!verifyLine(line)) {\\n        return \\"\\";\\n    }\\n\\n    return line;\\n}\\n\\n/**\\n * 验证CRC\\n *\\n * @param line 行信息\\n * @returns {boolean} 是否成功\\n */\\nfunction verifyLine(line) {\\n    if (line.length < 16) {\\n        return false;\\n    }\\n\\n    var body = line.substring(2, line.length - 6);\\n\\n    // 校验帧长度\\n    var size = parseInt(line.substring(6, 8), 16);\\n    size += parseInt(line.substring(8, 10), 16) * 0x100;\\n    if (line.length != 16 + size * 2) {\\n        return false;\\n    }\\n\\n\\n    var ch = line.substring(line.length - 4, line.length - 2);\\n    var cl = line.substring(line.length - 6, line.length - 4);\\n    var crc = calculateCRC16(body, 0xFFFF, 0xA001);\\n\\n    return crc === ch + cl;\\n}\\n\\n/**\\n * CRC16校验\\n * 范例：calculateCRC16(\\"7E0000000133000100\\", 0x0000, 0xA001);\\n *\\n * @param dataHexString 无空格的HEX格式文本，例如：\\"7E0000000133000100\\";\\n * @param init CRC16的初始值，例如：0x0000\\n * @param poly CRC16的多项式，例如：0xA001\\n * @returns {string}\\n */\\nfunction calculateCRC16(dataHexString, init, poly) {\\n    var dataBytes = [];\\n    for (var i = 0; i < dataHexString.length; i += 2) {\\n        dataBytes.push(parseInt(dataHexString.substring(i, i + 2), 16));\\n    }\\n\\n    var crc = init;\\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\\n\\n    for (var i = 0; i < dataBytes.length; i++) {\\n        crc ^= dataBytes[i];\\n        for (var j = 0; j < 8; j++) {\\n            if (crc & 0x0001) {\\n                crc = ((crc >> 1) ^ polynomial) & 0xFFFF;\\n            } else {\\n                crc >>= 1;\\n            }\\n        }\\n    }\\n\\n    crc = crc & 0xffff\\n\\n    var txt = crc.toString(16).toUpperCase();\\n    txt = padStart(txt,4,\'0\');\\n    return txt;\\n}\\n\\nfunction padStart(str, length, ch) {\\n    while (str.length < length) {\\n        str = ch + str;\\n    }\\n\\n    return str;\\n}", "main": "include"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\nFE 01 6E 22 00 01 00 01 01 03 02 00 09 01 19 12 31 12 35 17 02 16 0F 1B 5A 28 28 2A 15 31 49 2C 08 FF FF FF FF FF FF 68 7B FF \\n\\n测试报文2：\\nFE 01 00 01 00 00 48 00 FF\\n\\n测试报文3：\\nFE 01 64 01 00 64 56 DB FF\\n\\n"}', 'include', 'record', 1, 2000, 1727011534553, 1727011534553),
	(620, '心跳', 'JB-3208G', '上海松江飞繁电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (!obj.success) {\\n        return \\"解码失败\\";\\n    }\\n\\n    // 心跳包\\n    if (obj.type === \'64\') {\\n        var entity = {\\n            \\"心跳\\": new Date()\\n        };\\n        return entity;\\n    }\\n\\n    return \\"\\";\\n}", "main": "decode"}}', '{"description": "报文格式：\\n【报头】【未知】【类型】【长度】【数据】【校验】【报尾】\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n解读：\\nFE       报头（1字节）\\n01       未知（1字节）\\n64       类型（1字节）\\n01 00  长度（2字节）\\n64       数据（N字节）\\n56 DB 校验和（2字节 CRC16-MODBUS）\\nFF       包尾（1字节）\\n\\n范例1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\nFE 01 64 01 00 64 56 DB FF\\n\\n"}', 'report', 'status', 1, 2000, 1727011534565, 1727011534565),
	(621, '上报事件', 'JB-TGL-TX3006C', '泰和安消防科技有限公司', 'JavaScript', 'device', '{"decode": {"code": "/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\nfunction decodeStr(message, device_param) {\\n    // 检查：是否解码器成功\\n    var obj = decodeObj(message);\\n    if (obj.success === false) {\\n        return obj.message;\\n    }\\n\\n    // 检查：是否为心跳\\n    if (obj.type === \'0001\') {\\n        return null;\\n    }\\n\\n    // 必须包含recordType字段，用来指明事件的类型\\n    var record = {\\n        \\"recordType\\": \\"未识别\\", \\"info\\": obj\\n    };\\n\\n\\n    if (obj.data.length === 38) {\\n        var item1 = obj.data.substring(0, 1 * 2);\\n        var item2 = obj.data.substring(1 * 2, 4 * 2);\\n        var devCode = obj.data.substring(4 * 2, 6 * 2);\\n        var actCode = obj.data.substring(6 * 2, 8 * 2);\\n        var item5 = obj.data.substring(8 * 2, 11 * 2);\\n        var item6 = obj.data.substring(11 * 2, 17 * 2);\\n        var item7 = obj.data.substring(17 * 2, 19 * 2);\\n\\n        // 格式化设备地址\\n        var devAdr = formatDevAdr(item2);\\n\\n        // 格式化时间\\n        var time = formatTime(item6);\\n\\n        // 格式化设备名称\\n        var actName = formatActName(actCode);\\n\\n        // 格式化设备名称\\n        var devName = formatDevName(devCode);\\n\\n        record = {\\n            \\"recordType\\": actName, \\"time\\": time, \\"devAdr\\": devAdr, \\"deviceType\\": devName,\\n        };\\n    }\\n\\n\\n    // 必须以列表格式返回\\n    var result = [];\\n    result.push(record);\\n\\n    return result;\\n}\\n", "main": "decode"}}', '{"description": "报文格式：\\n1、由多行报文，组成一帧数据\\n2、行特征：每行以7E 00 00开始，以7E结束，采用CRC16-IBM校验\\n3、行格式：\\n范例：【7E 00 00】【00 01】  【32】  【00】【 01】  【 00】 【 1B 4A】【7E】 \\n说明：【行头】    【帧类型】【帧号】 【行号】【长度】【数据】 【CRC16】【行尾】\\n4、同一帧，帧号都相同，行号从01递增，最后一行以00结束\\n\\n范例：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E \\n7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E \\n7E 00 00 01 01 29 03 01 20 ED A7 7E \\n7E 00 00 01 01 29 00 02 0F 00 8B 39 7E \\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E 7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E 7E 00 00 01 01 29 03 01 20 ED A7 7E 7E 00 00 01 01 29 00 02 0F 00 8B 39 7E\\n\\n"}', 'report', 'record', 1, 2000, 1727011535221, 1727011535221),
	(622, '动作代码', 'JB-TGL-TX3006C', '泰和安消防科技有限公司', 'JavaScript', 'device', '{"include": {"code": "function formatActName(actCode) {\\n    if (actCode === \'0003\') {\\n        return \\"火警\\";\\n    }\\n    if (actCode === \'0013\') {\\n        return \\"启动\\";\\n    }\\n    if (actCode === \'001D\') {\\n        return \\"停动\\";\\n    }\\n    if (actCode === \'0052\') {\\n        return \\"主电故障\\";\\n    }\\n    if (actCode === \'0053\') {\\n        return \\"主电恢复\\";\\n    }\\n    if (actCode === \'0066\') {\\n        return \\"备电故障\\";\\n    }\\n    if (actCode === \'0067\') {\\n        return \\"备电恢复\\";\\n    }\\n    if (actCode === \'0051\') {\\n        return \\"通讯故障\\";\\n    }\\n    if (actCode === \'0065\') {\\n        return \\"通讯故障恢复\\";\\n    }\\n\\n    return \\"未定义的事件：\\" + actCode;\\n}\\n", "main": "include"}}', '{"description": "报文格式：\\n1、由多行报文，组成一帧数据\\n2、行特征：每行以7E 00 00开始，以7E结束，采用CRC16-IBM校验\\n3、行格式：\\n范例：【7E 00 00】【00 01】  【32】  【00】【 01】  【 00】 【 1B 4A】【7E】 \\n说明：【行头】    【帧类型】【帧号】 【行号】【长度】【数据】 【CRC16】【行尾】\\n4、同一帧，帧号都相同，行号从01递增，最后一行以00结束\\n\\n范例：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E \\n7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E \\n7E 00 00 01 01 29 03 01 20 ED A7 7E \\n7E 00 00 01 01 29 00 02 0F 00 8B 39 7E \\n\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E 7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E 7E 00 00 01 01 29 03 01 20 ED A7 7E 7E 00 00 01 01 29 00 02 0F 00 8B 39 7E\\n"}', 'include', 'record', 1, 2000, 1727011535239, 1727011535239),
	(623, 'splitHandler', 'JB-TGL-TX3006C', '泰和安消防科技有限公司', 'JavaScript', 'channel', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decode(message) {\\n    var starTag = \\"7E 00 00\\";\\n    var endTag = \\"7E\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    while (true) {\\n        var line = getNext(message, starTag, endTag);\\n        if (line.length > 0) {\\n            return line;\\n        }\\n\\n        message = message.substring(endTag.length);\\n        if (message.length == 0) {\\n            return \\"\\";\\n        }\\n    }\\n\\n    return \\"\\";\\n\\n}\\n\\nfunction getNext(message, starTag, endTag) {\\n    // 找到完整的段落\\n    var section = getSection(message, starTag, endTag);\\n    if (section.start === -1 || section.end === -1) {\\n        return \\"\\";\\n    }\\n\\n    var lines = message.substring(section.start, section.end);\\n\\n    return lines;\\n}\\n\\nfunction getSection(message, starTag, endTag) {\\n    var data = {\\n        \\"start\\": -1, \\"end\\": -1,\\n    }\\n\\n    // 找到起始符\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return data;\\n    }\\n\\n    // 切掉前面的数据\\n    var hexs = message.substring(start);\\n\\n    var end = 0;\\n    while (hexs.length > 0) {\\n        // 切出一行\\n        var line = getLine(hexs, starTag, endTag);\\n        if (line.length === 0) {\\n            return data;\\n        }\\n\\n        end += line.length;\\n\\n        var nextLn = getLn(line);\\n\\n        if (nextLn === \'00\') {\\n            data.start = start;\\n            data.end = start + end;\\n            return data;\\n        }\\n\\n        hexs = hexs.substring(line.length, hexs.length);\\n    }\\n\\n    // 场景1：找多行粘连时的结束符，此时可能存在，也可能不存在0A0A\\n    var endStart = hexs.indexOf(endTag + starTag, start + starTag.length);\\n    if (endStart >= 0) {\\n        data.start = start;\\n        data.end = start + endStart + endTag.length;\\n        return data;\\n    }\\n\\n    // 场景2：单行场景\\n    var end = hexs.indexOf(endTag, start + starTag.length);\\n    if (end < 0) {\\n        return data;\\n    }\\n\\n    data.start = start;\\n    data.end = start + end;\\n    return data;\\n}\\n\\n\\n/**\\n * 从行中取出行号\\n * 例如：7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E\\n * 其中的01\\n *\\n * @param line 行信息\\n * @returns {string}\\n */\\nfunction getLn(line) {\\n    return line.substring(12, 14);\\n}\\n\\n/**\\n * 分拆行\\n * @param message 消息\\n * @param starTag 起始符\\n * @param endTag 结束符\\n * @returns {string} 行\\n */\\nfunction getLine(message, starTag, endTag) {\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start !== 0) {\\n        return \\"\\";\\n    }\\n\\n    // 检测：最小长度\\n    if (message.length < 22) {\\n        return \\"\\";\\n    }\\n\\n    // 数据大小\\n    var size = parseInt(message.substring(14, 16), 16);\\n\\n    // 切第一行\\n    var line = message.substring(start, start + 22 + size * 2);\\n    if (line.substring(line.length - endTag.length, line.length) !== endTag) {\\n        return \\"\\";\\n    }\\n\\n    // 截取第一行，并进行行验证\\n    if (!verifyLine(line)) {\\n        return \\"\\";\\n    }\\n\\n    return line;\\n}\\n\\n/**\\n * 验证CRC\\n *\\n * @param line 行信息\\n * @returns {boolean} 是否成功\\n */\\nfunction verifyLine(line) {\\n    if (line.length < 24) {\\n        return false;\\n    }\\n\\n    var body = line.substring(0, line.length - 6);\\n\\n    // 校验帧长度\\n    var len = parseInt(line.substring(14, 16), 16);\\n    if (line.length != 22 + len * 2) {\\n        return false;\\n    }\\n\\n\\n    var ch = line.substring(body.length, body.length + 2);\\n    var cl = line.substring(body.length + 2, body.length + 4);\\n    var crc = calculateCRC16(body, 0x0000, 0xA001);\\n\\n    return crc === cl + ch;\\n}\\n\\n/**\\n * CRC16校验\\n * 范例：calculateCRC16(\\"7E0000000133000100\\", 0x0000, 0xA001);\\n *\\n * @param dataHexString 无空格的HEX格式文本，例如：\\"7E0000000133000100\\";\\n * @param init CRC16的初始值，例如：0x0000\\n * @param poly CRC16的多项式，例如：0xA001\\n * @returns {string}\\n */\\nfunction calculateCRC16(dataHexString, init, poly) {\\n    var dataBytes = [];\\n    for (var i = 0; i < dataHexString.length; i += 2) {\\n        dataBytes.push(parseInt(dataHexString.substring(i, i + 2), 16));\\n    }\\n\\n    var crc = init;\\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\\n\\n    for (var i = 0; i < dataBytes.length; i++) {\\n        crc ^= dataBytes[i];\\n        for (var j = 0; j < 8; j++) {\\n            if (crc & 0x0001) {\\n                crc = ((crc >> 1) ^ polynomial) & 0xFFFF;\\n            } else {\\n                crc >>= 1;\\n            }\\n        }\\n    }\\n\\n    crc = crc & 0xffff\\n\\n    var txt = crc.toString(16).toUpperCase();\\n    txt = padStart(txt, 4, \'0\');\\n    return txt;\\n}\\n\\nfunction padStart(str, length, ch) {\\n    while (str.length < length) {\\n        str = ch + str;\\n    }\\n\\n    return str;\\n}\\n", "main": "decode"}}', '{"description": "报文格式：\\n1、由多行报文，组成一帧数据\\n2、行特征：每行以7E 00 00开始，以7E结束，采用CRC16-IBM校验\\n3、行格式：\\n范例：【7E 00 00】【00 01】  【32】  【00】【 01】  【 00】 【 1B 4A】【7E】 \\n说明：【行头】    【帧类型】【帧号】 【行号】【长度】【数据】 【CRC16】【行尾】\\n4、同一帧，帧号都相同，行号从01递增，最后一行以00结束\\n\\n范例：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E \\n7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E \\n7E 00 00 01 01 29 03 01 20 ED A7 7E \\n7E 00 00 01 01 29 00 02 0F 00 8B 39 7E \\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E 7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E 7E 00 00 01 01 29 03 01 20 ED A7 7E 7E 00 00 01 01 29 00 02 0F 00 8B 39 7E\\n\\n"}', 'splitHandler', 'status', 1, 2000, 1727011535253, 1727011535253),
	(624, '设备代码', 'JB-TGL-TX3006C', '泰和安消防科技有限公司', 'JavaScript', 'device', '{"include": {"code": "\\nfunction formatDevName(devCode) {\\n    if (devCode === \'003D\') {\\n        return \\"手动火灾报警按钮\\";\\n    }\\n    if (devCode === \'003E\') {\\n        return \\"消火栓按钮\\";\\n    }\\n    if (devCode === \'00B8\') {\\n        return \\"喷淋泵\\";\\n    }\\n    if (devCode === \'0001\') {\\n        return \\"本机电源\\";\\n    }\\n    if (devCode === \'003D\') {\\n        return \\"手动火灾按钮报警\\";\\n    }\\n    if (devCode === \'0017\') {\\n        return \\"点型光电感烟探测器\\";\\n    }\\n\\n    return \\"未定义的事件：\\" + devCode;\\n}\\n", "main": "include"}}', '{"description": "测试发现：泰和安的设备，同样的设备代码，在不同的设备上，指定色设备，定义大相径庭\\n所以，这边将设备名称的识别函数，单独分离出来\\n\\n那么，到现场安装测试阶段的时候，通过核对，可以重新修改这个设备代码的定义"}', 'include', 'record', 1, 2000, 1727011535264, 1727011535264),
	(625, 'libs', 'JB-TGL-TX3006C', '泰和安消防科技有限公司', 'JavaScript', 'device', '{"include": {"code": "\\n/**\\n * 按类型解码数据\\n * @param message 消息内容\\n * @returns {{data, success, sn, type, message}}\\n */\\nfunction decodeObj(message) {\\n    var starTag = \\"7E 00 00\\";\\n    var endTag = \\"7E\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    // 找到起始符\\n    var firstStart = message.indexOf(starTag);\\n    if (firstStart < 0) {\\n        return buildResult(\\"\\", \\"\\", \\"\\", false, \\"找不到起始符\\");\\n    }\\n\\n    // 切掉前面的数据\\n    message = message.substring(firstStart);\\n\\n    // 切出第一行\\n    var firstLine = getLine(message, starTag, endTag);\\n    if (firstLine.length === 0) {\\n        return buildResult(\\"\\", \\"\\", \\"\\", false, \\"行格式不正确\\");\\n    }\\n\\n\\n    // 取出行信息\\n    var firstType = getType(firstLine);\\n    var firstSn = getSn(firstLine);\\n    var firstLn = getLn(firstLine);\\n    var firstData = getData(firstLine);\\n\\n\\n    // 检查：第1行是否为结束行\\n    if (firstLn === \'00\') {\\n        return buildResult(firstType, firstSn, firstData, true, \\"\\");\\n    }\\n\\n\\n    var fullData = firstData;\\n\\n\\n    // 寻找后续多行\\n    var lines = message.substring(firstLine.length, message.length);\\n    for (var i = 0; i < 8; i++) {\\n        // 校验：是否以起始符开始\\n        var nextStart = lines.indexOf(starTag);\\n        if (nextStart < 0) {\\n            return buildResult(\\"\\", \\"\\", \\"\\", false, \\"找不到起始符\\");\\n        }\\n\\n        // 切下一行\\n        var nextLine = getLine(lines, starTag, endTag);\\n        if (nextLine.length === 0) {\\n            return buildResult(\\"\\", \\"\\", \\"\\", false, \\"行格式不正确\\");\\n        }\\n\\n        // 剔除找到的行\\n        lines = lines.substring(nextLine.length, message.length);\\n\\n\\n        var nextType = getType(nextLine);\\n        var nextSn = getSn(nextLine);\\n        var nextLn = getLn(nextLine);\\n        var nextData = getData(nextLine);\\n\\n        fullData += nextData;\\n\\n        if (nextLn === \'00\') {\\n            return buildResult(firstType, firstSn, fullData, true, \\"\\");\\n        }\\n\\n        // 检查：是否到达下一组数据\\n        if (firstType !== nextType || firstSn !== nextSn) {\\n            return buildResult(\\"\\", \\"\\", \\"\\", false, \\"行信息不对齐\\");\\n        }\\n    }\\n\\n    return buildResult(\\"\\", \\"\\", \\"\\", false, \\"验证不通过\\");\\n}\\n\\n\\nfunction formatDevAdr(tagAdr) {\\n    var devAdr = padStart(String(parseInt(tagAdr.substring(0, 2), 16)), 3, \'0\');\\n    devAdr += padStart(String(parseInt(tagAdr.substring(2, 4), 16)), 2, \'0\');\\n    devAdr += padStart(String(parseInt(tagAdr.substring(4, 6), 16)), 3, \'0\');\\n\\n    return devAdr;\\n}\\n\\nfunction formatTime(tagTime) {\\n    var time = \'20\' + parseInt(tagTime.substring(0, 2), 16);\\n    time += \'-\';\\n    time += padStart(String(parseInt(tagTime.substring(2, 4), 16)), 2, \'0\');\\n    time += \'-\';\\n    time += padStart(String(parseInt(tagTime.substring(4, 6), 16)), 2, \'0\');\\n    time += \' \';\\n    time += padStart(String(parseInt(tagTime.substring(6, 8), 16)), 2, \'0\');\\n    time += \':\';\\n    time += padStart(String(parseInt(tagTime.substring(8, 10), 16)), 2, \'0\');\\n    time += \':\';\\n    time += padStart(String(parseInt(tagTime.substring(10, 12), 16)), 2, \'0\');\\n\\n    return time;\\n}\\n\\n/**\\n * 生成返回的结构\\n * @param type 类型\\n * @param sn 流水号\\n * @param data 数据\\n * @param success 是否成功\\n * @param message 异常信息\\n * @returns {{data, success, sn, type, message}}\\n */\\nfunction buildResult(type, sn, data, success, message) {\\n    return {\\n        \\"type\\": type, \\"sn\\": sn, \\"data\\": data, \\"success\\": success, \\"message\\": message\\n    };\\n}\\n\\n/**\\n * 从行中取出帧类型\\n *\\n * @param line 行信息\\n * @returns {string} 帧类型，例如：0101\\n */\\nfunction getType(line) {\\n    return line.substring(6, 10);\\n}\\n\\n/**\\n * 从行中取出帧序号\\n *\\n * @param line 行信息，例如：38\\n * @returns {string}\\n */\\nfunction getSn(line) {\\n    return line.substring(10, 12);\\n}\\n\\n/**\\n * 从行中取出行号\\n * 例如：7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E\\n * 其中的01\\n *\\n * @param line 行信息\\n * @returns {string}\\n */\\nfunction getLn(line) {\\n    return line.substring(12, 14);\\n}\\n\\n/**\\n * 从行中取出数据区\\n * 例如：7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E\\n * 其中的05 01 01 66 00 3D 00 03\\n *\\n * @param line 行信息\\n * @returns {string}\\n */\\nfunction getData(line) {\\n    return line.substring(16, line.length - 6);\\n}\\n\\n/**\\n * 分拆行\\n * @param message 消息\\n * @param starTag 起始符\\n * @param endTag 结束符\\n * @returns {string} 行\\n */\\nfunction getLine(message, starTag, endTag) {\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start !== 0) {\\n        return \\"\\";\\n    }\\n\\n    // 检测：最小长度\\n    if (message.length < 22) {\\n        return \\"\\";\\n    }\\n\\n    // 数据大小\\n    var size = parseInt(message.substring(14, 16), 16);\\n\\n    // 切第一行\\n    var line = message.substring(start, start + 22 + size * 2);\\n    if (line.substring(line.length - endTag.length, line.length) !== endTag) {\\n        return \\"\\";\\n    }\\n\\n    // 截取第一行，并进行行验证\\n    if (!verifyLine(line)) {\\n        return \\"\\";\\n    }\\n\\n    return line;\\n}\\n\\n/**\\n * 验证CRC\\n *\\n * @param line 行信息\\n * @returns {boolean} 是否成功\\n */\\nfunction verifyLine(line) {\\n    if (line.length < 24) {\\n        return false;\\n    }\\n\\n    var body = line.substring(0, line.length - 6);\\n\\n    // 校验帧长度\\n    var len = parseInt(line.substring(14, 16), 16);\\n    if (line.length != 22 + len * 2) {\\n        return false;\\n    }\\n\\n\\n    var ch = line.substring(body.length, body.length + 2);\\n    var cl = line.substring(body.length + 2, body.length + 4);\\n    var crc = calculateCRC16(body, 0x0000, 0xA001);\\n\\n    return crc === cl + ch;\\n}\\n\\n/**\\n * CRC16校验\\n * 范例：calculateCRC16(\\"7E0000000133000100\\", 0x0000, 0xA001);\\n *\\n * @param dataHexString 无空格的HEX格式文本，例如：\\"7E0000000133000100\\";\\n * @param init CRC16的初始值，例如：0x0000\\n * @param poly CRC16的多项式，例如：0xA001\\n * @returns {string}\\n */\\nfunction calculateCRC16(dataHexString, init, poly) {\\n    var dataBytes = [];\\n    for (var i = 0; i < dataHexString.length; i += 2) {\\n        dataBytes.push(parseInt(dataHexString.substring(i, i + 2), 16));\\n    }\\n\\n    var crc = init;\\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\\n\\n    for (var i = 0; i < dataBytes.length; i++) {\\n        crc ^= dataBytes[i];\\n        for (var j = 0; j < 8; j++) {\\n            if (crc & 0x0001) {\\n                crc = ((crc >> 1) ^ polynomial) & 0xFFFF;\\n            } else {\\n                crc >>= 1;\\n            }\\n        }\\n    }\\n\\n    crc = crc & 0xffff\\n\\n    var txt = crc.toString(16).toUpperCase();\\n    txt = padStart(txt,4,\'0\');\\n    return txt;\\n}\\n\\nfunction padStart(str, length, ch) {\\n    while (str.length < length) {\\n        str = ch + str;\\n    }\\n\\n    return str;\\n}", "main": "include"}}', '{"description": "报文格式：\\n1、由多行报文，组成一帧数据\\n2、行特征：每行以7E 00 00开始，以7E结束，采用CRC16-IBM校验\\n3、行格式：\\n范例：【7E 00 00】【00 01】  【32】  【00】【 01】  【 00】 【 1B 4A】【7E】 \\n说明：【行头】    【帧类型】【帧号】 【行号】【长度】【数据】 【CRC16】【行尾】\\n4、同一帧，帧号都相同，行号从01递增，最后一行以00结束\\n\\n范例：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E \\n7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E \\n7E 00 00 01 01 29 03 01 20 ED A7 7E \\n7E 00 00 01 01 29 00 02 0F 00 8B 39 7E \\n\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n7E 00 00 01 01 29 01 08 05 01 01 66 00 3D 00 03 E5 70 7E 7E 00 00 01 01 29 02 08 00 00 00 18 01 0F 0B 0D CA 9C 7E 7E 00 00 01 01 29 03 01 20 ED A7 7E 7E 00 00 01 01 29 00 02 0F 00 8B 39 7E\\n"}', 'include', 'record', 1, 2000, 1727011535276, 1727011535276),
	(626, '首警', 'JB-QB-TX3001DY', '泰和安消防科技有限公司', 'JavaScript', 'device', '{"decode": {"code": "/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"首警\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以\\n2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A\\n开始，\\n以多行\\n00 00 00 00 00 00 00 00 00 00 00 00 0A \\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 32 33 2D 30 39 2D 30 38 20 31 33 3A 30 35 3A 35 36 0A CA D7 BE AF 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 0A 30 30 31 30 31 30 30 31 20 B5 E3 D0 CD B9 E2 B5 E7 B8 D0 D1 CC 00 00 00 00 0A 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 0A \\n\\n报文内容：\\n首警\\n00101001 点型光电感烟\\n"}', 'report', 'record', 1, 2000, 1727011536073, 1727011536073),
	(627, '多线点启动', 'JB-QB-TX3001DY', '泰和安消防科技有限公司', 'JavaScript', 'device', '{"decode": {"code": "/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"多线点启动\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以\\n2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A\\n开始，\\n以多行\\n00 00 00 00 00 00 00 00 00 00 00 00 0A \\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 32 33 2D 30 39 2D 30 38 20 31 33 3A 33 39 3A 34 36 0A B6 E0 CF DF B5 E3 C6 F4 B6 AF 00 00 00 00 00 00 00 00 00 00 0A 38 34 30 30 30 30 30 31 20 CF FB B7 C0 CB A8 B1 C3 00 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 0A \\n\\n报文内容：\\n********************************23-09-08 13:39:46\\n多线点启动\\n84000001 消防栓泵\\n\\n"}', 'report', 'record', 1, 2000, 1727011536089, 1727011536089),
	(628, 'splitHandler', 'JB-QB-TX3001DY', '泰和安消防科技有限公司', 'JavaScript', 'channel', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decode(message) {\\n    var starTag = \\"2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A\\";\\n    var endTag = \\"00 00 00 00 00 00 00 00 00 00 00 00 0A\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找第一个结束标记\\n    var end = message.indexOf(endTag);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    while (true) {\\n        var line = getLine(message, starTag, endTag);\\n        if (line.length > 0) {\\n            return line;\\n        }\\n\\n        message = message.substring(endTag.length);\\n        if (message.length == 0) {\\n            return \\"\\";\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n\\nfunction getLine(message, starTag, endTag) {\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找第一个结束标记\\n    var end = message.indexOf(endTag);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找后续多行\\n    var lines = message.substring(start, message.length);\\n    for (var i = 0; i < 8; i++) {\\n        var next = lines.indexOf(starTag, end + 2);\\n        var pos = lines.indexOf(endTag, end + 2);\\n\\n        // 检查：是否还有下一行，或者出现了实际上的下一行换行符\\n        if (pos < 0 || pos > next) {\\n            break;\\n        }\\n\\n        end = pos;\\n    }\\n\\n    // 分拆数据\\n    var data = message.substring(start, end + endTag.length);\\n\\n\\n    // 截取数据\\n    var result = data;\\n\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以\\n2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A\\n开始，\\n以多行\\n00 00 00 00 00 00 00 00 00 00 00 00 0A \\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 2A 32 33 2D 30 39 2D 30 38 20 31 33 3A 33 39 3A 33 34 0A B7 B4 C0 A1 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 0A 30 30 31 30 31 30 32 37 20 CF FB BB F0 CB A8 B0 B4 C5 A5 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 0A\\n\\n报文内容：\\n********************************23-09-08 13:39:34\\n反馈\\n00101027 消火栓按钮"}', 'splitHandler', 'status', 1, 2000, 1727011536100, 1727011536100),
