	(652, '故障', 'JB-QG-LD128E(Q)II', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"故障\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以1B 40 1B 31 05 1B 36 1B 39开始，以0A 1B 4A 01 1B 39 字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1B 31 05 1B 36 1B 39 31 39 2F 30 36 2F 32 31 20 31 30 3A 31 35 3A 32 37 0A 30 30 C2 A5 30 32 B2 E3 30 30 B7 BF BC E4 0A D7 DF B5 C0 D3 D2 00 00 00 00 0A 00 00 00 00 00 00 00 00 00 00 00 00 0A B9 CA D5 CF 3A 30 30 31 32 31 0A CA D6 B1 A8 0A 1B 4A 01 1B 39\\n\\n\\n报文内容：\\n\\u001b@\\u001b1\\u0005\\u001b6\\u001b919/06/21 10:15:27\\n00楼02层00房间\\n走道右\\n\\n故障:00121\\n手报\\n\\u001bJ\\u0001\\u001b9\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文2：\\n\\n1B 40 1B 31 05 1B 36 1B 39 31 39 2F 30 36 2F 3231 20 31 30 3A 35 33 3A 32 30 0A 30 30 C2 A5 3032 B2 E3 30 30 B7 BF BC E4 0A B5 E7 CC DD C7 B0CA D2 00 00 0A 00 00 00 00 00 00 00 00 00 00 0000 0A B9 CA D5 CF 3A 30 30 31 30 32 0A B8 D0 D1CC 0A 1B 4A 01 1B 39\\n\\n\\n"}', 'report', 'record', 1, 2000, 1727011619553, 1727011619553),
	(653, 'libs', 'JB-QG-LD128E(Q)II', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"include": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 按类型解码数据\\n *\\n * @param message 消息内容\\n * @param typeHeadTag 类型\\n * @returns {string|*[]} 数据\\n */\\nfunction decodeType(message, typeHeadTag) {\\n    var lines = message.split(\'\\\\n\');\\n\\n    // 剔除空行\\n    lines = removeEmpty(lines);\\n    if (lines.length < 2) {\\n        return \\"行数小于2\\";\\n    }\\n\\n    var timeHeadTag = \\"\\u001b@\\u001b1\\u0005\\u001b6\\u001b9\\";\\n    var tailHeadTag = \\"\\u001bJ\\u0001\\u001b9\\";\\n\\n    var timeLine = findLine(lines, timeHeadTag);\\n    var typeLine = findLine(lines, typeHeadTag);\\n\\n\\n    if (typeLine.length !== 0 && timeLine.length !== 0) {\\n        lines = removeLine(lines, tailHeadTag);\\n        lines = removeLine(lines, timeLine);\\n        lines = removeLine(lines, typeLine);\\n\\n        var oid = \'\';\\n        var items = typeLine.split(\':\');\\n        if (items.length > 1) {\\n            oid = items[1];\\n        }\\n\\n\\n        var almTime = timeLine.substring(timeHeadTag.length);\\n\\n        // 必须包含recordType字段，用来指明事件的类型\\n        var obj = {\\n            \\"recordType\\": typeHeadTag, \\"oid\\": oid, \\"datetime\\": almTime, \\"data\\": lines\\n        };\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        result.push(obj);\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}\\n\\nfunction removeLine(array, line) {\\n    var dats = [];\\n    for (i = 0; i < array.length; i++) {\\n        if (array[i] === line) {\\n            continue;\\n        }\\n        dats.push(array[i]);\\n    }\\n\\n    return dats;\\n}\\n\\nfunction removeEmpty(lines) {\\n    var dats = [];\\n    for (var i = 0; i < lines.length; i++) {\\n        var line = lines[i].replace(/\\\\u0000/g, \'\');\\n        if (line.length == 0) {\\n            continue;\\n        }\\n\\n        dats.push(line);\\n    }\\n\\n    return dats;\\n}\\n\\nfunction findLine(lines, headTag) {\\n    for (var i = 0; i < lines.length; i++) {\\n        if (lines[i].indexOf(headTag) == 0) {\\n            return lines[i];\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n", "main": "include"}}', '{"description": "报文格式：\\n以1B 40 1B 31 05 1B 36 1B 39开始，以0A 1B 4A 01 1B 39 字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1B 31 05 1B 36 1B 39 32 31 2F 30 34 2F 30 32 20 31 36 3A 34 33 3A 34 33 0A 30 30 C2 A5 30 30 B2 E3 30 30 B7 BF BC E4 0A 00 00 00 00 00 00 00 00 00 00 0A BB EE B6 AF D6 D0 D0 C4 A3 B1 A3 C6 0A B9 CA D5 CF 3A 30 30 31 36 37 0A CF FB BB F0 CB A8 B0 B4 C5 A5 0A 1B 4A 01 1B 39\\n\\n\\n报文内容：\\n\\u001b@\\u001b1\\u0005\\u001b6\\u001b921/04/02 16:43:43\\n00楼00层00房间\\n\\n活动中心１Ｆ\\n故障:00167\\n消火栓按钮\\n\\u001bJ\\u0001\\u001b9\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文2：\\n\\n1B 40 1B 31 05 1B 36 1B 39 32 31 2F 30 34 2F 30 32 20 31 36 3A 34 39 3A 35 34 0A 30 30 C2 A5 30 30 B2 E3 30 30 B7 BF BC E4 0A 00 00 00 00 00 00 00 00 00 00 0A BB EE B6 AF D6 D0 D0 C4 A3 B1 A3 C6 0A B9 CA D5 CF 3A 30 30 31 33 31 0A CA D6 B1 A8 0A 1B 4A 01 1B 39\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文3：\\n\\n1B 40 1B 31 05 1B 36 1B 39 32 31 2F 30 34 2F 30 32 20 31 36 3A 35 31 3A 35 37 0A 30 30 C2 A5 30 30 B2 E3 30 30 B7 BF BC E4 0A 00 00 00 00 00 00 00 00 00 00 0A BB EE B6 AF D6 D0 D0 C4 A3 B4 A3 C6 0A B9 CA D5 CF 3A 30 30 32 31 34 0A D0 C5 BA C5 B7 A7 0A 1B 4A 01 1B 39\\n\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文4：\\n\\n1B 40 1B 31 05 1B 36 1B 39 32 31 2F 30 34 2F 30 32 20 31 36 3A 35 39 3A 31 32 0A 30 30 C2 A5 30 30 B2 E3 30 30 B7 BF BC E4 0A 00 00 00 00 00 00 00 00 00 00 0A BB EE B6 AF D6 D0 D0 C4 A3 B4 A3 C6 0A B9 CA D5 CF 3A 30 30 31 32 38 0A B8 D0 D1 CC 0A 1B 4A 01 1B 39\\n\\n\\n"}', 'include', 'record', 1, 2000, 1727011619564, 1727011619564),
	(654, 'splitHandler', 'JB-QT-LD188EL', '北京利达华信电子有限公司', 'JavaScript', 'channel', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decode(message) {\\n    var starTag = \\"1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 \\";\\n    var endTag = \\"0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找第一个结束标记\\n    var end = message.indexOf(endTag);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    while (true) {\\n        var line = getLine(message, starTag, endTag);\\n        if (line.length > 0) {\\n            return line;\\n        }\\n\\n        message = message.substring(endTag.length);\\n        if (message.length == 0) {\\n            return \\"\\";\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n\\nfunction getLine(message, starTag, endTag) {\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找第一个结束标记\\n    var end = message.indexOf(endTag);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找后续多行\\n    var lines = message.substring(start, message.length);\\n    for (var i = 0; i < 8; i++) {\\n        var next = lines.indexOf(starTag, end + 2);\\n        var pos = lines.indexOf(endTag, end + 2);\\n\\n        // 检查：是否还有下一行，或者出现了实际上的下一行换行符\\n        if (pos < 0 || pos > next) {\\n            break;\\n        }\\n\\n        end = pos;\\n    }\\n\\n    // 分拆数据\\n    var data = message.substring(start, end + endTag.length);\\n\\n\\n    // 截取数据\\n    var result = data;\\n\\n    return result;\\n}\\n", "main": "decode"}}', '{"description": "报文格式：\\n以\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 \\n开始，\\n以\\n0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 33 3A 34 35 3A 34 34 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 B5 E7 B3 D8 B1 B8 B5 E7 0A 00 00 00 00 00 00 00 BF D8 D6 C6 C6 F7 B1 B8 B5 E7 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 B9 CA D5 CF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 \\n\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&13:45:44 21-06-09\\n电池备电\\n控制器备电     \\n故障     \\n\\n"}', 'splitHandler', 'status', 1, 2000, 1727011620198, 1727011620198),
	(655, '火警', 'JB-QT-LD188EL', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"火警\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 \\n开始，\\n以\\n0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 35 3A 34 32 3A 32 39 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 B3 C9 C6 B7 B6 FE C2 A5 0A 00 00 00 00 00 00 00 CF FB BB F0 CB A8 B0 B4 C5 A5 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 41 30 32 20 32 32 33 00 20 20 20 20 20 20 20 20 0A 00 00 00 00 00 00 00 BB F0 BE AF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 \\n\\n\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&15:42:29 21-06-09\\n成品二楼\\n消火栓按钮     \\nA02 223        \\n火警     \\n\\n"}', 'report', 'record', 1, 2000, 1727011620215,