	(656, '请求', 'JB-QT-LD188EL', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"请求\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 \\n开始，\\n以\\n0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 35 3A 34 32 3A 32 39 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 CF FB B7 C0 B1 C3 20 20 20 20 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 50 30 32 20 30 30 30 00 20 20 20 20 20 20 20 20 0A 00 00 00 00 00 00 00 C7 EB C7 F3 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 \\n\\n\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&15:42:29 21-06-09\\n消防泵         \\nP02 000        \\n请求     \\n\\n"}', 'report', 'record', 1, 2000, 1727011620225, 1727011620225),
	(657, '故障', 'JB-QT-LD188EL', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"故障\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 \\n开始，\\n以\\n0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 33 3A 34 35 3A 34 34 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 B5 E7 B3 D8 B1 B8 B5 E7 0A 00 00 00 00 00 00 00 BF D8 D6 C6 C6 F7 B1 B8 B5 E7 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 B9 CA D5 CF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 \\n\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&13:45:44 21-06-09\\n电池备电\\n控制器备电     \\n故障     \\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文2：\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 33 3A 35 33 3A 31 35 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 32 32 30 56 BD BB C1 F7 0A 00 00 00 00 00 00 00 BF D8 D6 C6 C6 F7 D6 F7 B5 E7 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 B9 CA D5 CF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\n\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&13:53:15 21-06-09\\n220V交流\\n控制器主电     \\n故障     \\n\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 35 3A 32 38 3A 32 32 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 B3 C9 C6 B7 B6 FE C2 A5 0A 00 00 00 00 00 00 00 CF FB BB F0 CB A8 B0 B4 C5 A5 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 41 30 32 20 32 32 33 00 20 20 20 20 20 20 20 20 0A 00 00 00 00 00 00 00 B9 CA D5 CF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 \\n\\n--------------------------------------------------------------------------------------------------------------------------\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&15:28:22 21-06-09\\n成品二楼\\n消火栓按钮     \\nA02 223        \\n故障     \\n\\n\\n"}', 'report', 'record', 1, 2000, 1727011620235, 1727011620235);
INSERT INTO `tb_operate` (`id`, `operate_name`, `device_type`, `manufacturer`, `engine_type`, `service_type`, `engine_param`, `extend_param`, `operate_mode`, `data_type`, `polling`, `timeout`, `create_time`, `update_time`) VALUES
	(658, 'libs', 'JB-QT-LD188EL', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"include": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2024. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 按类型解码数据\\n *\\n * @param message 消息内容\\n * @param typeHeadTag 类型\\n * @returns {string|*[]} 数据\\n */\\nfunction decodeType(message, typeHeadTag) {\\n    var lines = message.split(\'\\\\n\');\\n\\n    // 剔除空行\\n    lines = removeEmpty(lines);\\n    if (lines.length < 2) {\\n        return \\"行数小于2\\";\\n    }\\n\\n    // 获得首行和尾尾\\n    var timeLine = lines[0];\\n    var typeLine = lines[lines.length - 1];\\n\\n    // 清除空行\\n    lines = removeLine(lines, timeLine);\\n    lines = removeLine(lines, typeLine);\\n\\n\\n    var timeHeadTag = \\"\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&\\";\\n    if (typeLine.indexOf(typeHeadTag) == 0) {\\n        if (timeLine.indexOf(timeHeadTag) < 0) {\\n            return \\"格式不正确\\";\\n        }\\n\\n        // 查找\\n        var almTime = timeLine.substring(timeHeadTag.length);\\n\\n        // 查找地址行\\n        var addrLine = findAddress(lines);\\n\\n\\n        // 必须包含recordType字段，用来指明事件的类型\\n        var obj = \'\';\\n        if (addrLine.length !== 0) {\\n            // 剔除地址行\\n            lines = removeLine(lines, addrLine);\\n\\n            // 格式化地址行\\n            var address = formatAddress(addrLine);\\n\\n            obj = {\\n                \\"recordType\\": typeHeadTag, \\"datetime\\": almTime, \\"address\\": address, \\"data\\": lines\\n            };\\n        } else {\\n            obj = {\\n                \\"recordType\\": typeHeadTag, \\"datetime\\": almTime, \\"data\\": lines\\n            };\\n        }\\n\\n        // 必须以列表格式返回\\n        var result = [];\\n        result.push(obj);\\n\\n        return result;\\n    }\\n\\n    return \\"\\";\\n}\\n\\nfunction removeLine(array, line) {\\n    var dats = [];\\n    for (var i = 0; i < array.length; i++) {\\n        if (array[i] === line) {\\n            continue;\\n        }\\n        dats.push(array[i]);\\n    }\\n\\n    return dats;\\n}\\n\\nfunction removeEmpty(lines) {\\n    var dats = [];\\n    for (var i = 0; i < lines.length; i++) {\\n        var line = lines[i].replace(/\\\\u0000/g, \'\');\\n        if (line.length == 0) {\\n            continue;\\n        }\\n\\n        dats.push(line);\\n    }\\n\\n    return dats;\\n}\\n\\nfunction findAddress(lines) {\\n    for (var i = 0; i < lines.length; i++) {\\n        if (isAddress(lines[i])) {\\n            return lines[i];\\n        }\\n    }\\n\\n    return \\"\\";\\n}\\n\\n/**\\n * 用空格隔开的两个16进制格式\\n * @param line 一行数据\\n * @returns {boolean}\\n */\\nfunction isAddress(line) {\\n    // 分拆\\n    var items = line.split(\' \');\\n\\n    // 剔除空格\\n    items = removeEmpty(items);\\n\\n    if (items.length < 2) {\\n        return false;\\n    }\\n\\n    // 检查：是否为数字和字母\\n    for (var i = 0; i < items.length; i++) {\\n        var isHex = /^[0-9a-zA-Z]+$/.test(items[i]);\\n        if (isHex !== true) {\\n            return false\\n        }\\n    }\\n\\n    return true;\\n}\\n\\nfunction formatAddress(line) {\\n    // 分拆\\n    var items = line.split(\' \');\\n\\n    // 剔除空格\\n    items = removeEmpty(items);\\n\\n    if (items.length != 2) {\\n        return \'\';\\n    }\\n\\n    return items[0] + \' \' + items[1];\\n}\\n", "main": "include"}}', '{"description": "报文格式：\\n以\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 \\n开始，\\n以\\n0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\n字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 33 3A 34 35 3A 34 34 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 B5 E7 B3 D8 B1 B8 B5 E7 0A 00 00 00 00 00 00 00 BF D8 D6 C6 C6 F7 B1 B8 B5 E7 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 B9 CA D5 CF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 \\n\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&13:45:44 21-06-09\\n电池备电\\n控制器备电     \\n故障     \\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文2：\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 33 3A 35 33 3A 31 35 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 32 32 30 56 BD BB C1 F7 0A 00 00 00 00 00 00 00 BF D8 D6 C6 C6 F7 D6 F7 B5 E7 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 B9 CA D5 CF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00\\n\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&13:53:15 21-06-09\\n220V交流\\n控制器主电     \\n故障     \\n\\n1B 40 1C 69 00 1B 43 06 1B 78 00 1C 26 00 00 00 31 35 3A 32 38 3A 32 32 20 32 31 2D 30 36 2D 30 39 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 B3 C9 C6 B7 B6 FE C2 A5 0A 00 00 00 00 00 00 00 CF FB BB F0 CB A8 B0 B4 C5 A5 00 20 20 20 20 20 0A 00 00 00 00 00 00 00 41 30 32 20 32 32 33 00 20 20 20 20 20 20 20 20 0A 00 00 00 00 00 00 00 B9 CA D5 CF 20 20 20 20 00 20 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 0A 00 00 00 00 00 00 00 \\n\\n--------------------------------------------------------------------------------------------------------------------------\\n报文内容：\\n\\u001b@\\u001ci\\u001bC\\u0006\\u001bx\\u001c&15:28:22 21-06-09\\n成品二楼\\n消火栓按钮     \\nA02 223        \\n故障     \\n"}', 'include', 'record', 1, 2000, 1727011620245, 1727011620245),
	(659, '反馈', 'JB-QG-LD128E(Q)I', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"反馈\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以1B 40 1B 31 05 1B 36 1B 39开始，以0A 1B 4A 01 1B 39 字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1B 31 05 1B 36 1B 39 32 32 2F 30 38 2F 30 38 20 31 33 3A 32 30 3A 31 31 0A 30 30 C2 A5 30 30 B2 E3 30 30 B7 BF BC E4 0A 00 00 00 00 00 00 00 00 00 00 0A B3 AC CA D0 A3 B2 A3 C6 CE F7 00 00 0A B7 B4 C0 A1 3A 35 34 32 33 37 0A BE ED C1 B1 C3 C5 0A 1B 4A 01 1B 39\\n\\n报文内容：\\n\\u001b@\\u001b1\\u0005\\u001b6\\u001b922/08/08 13:20:11\\n00楼00层00房间\\n\\n超市２Ｆ西\\n反馈:54237\\n卷帘门\\n\\u001bJ\\u0001\\u001b9"}', 'report', 'record', 1, 2000, 1727011620818, 1727011620818),
	(660, '系统复位', 'JB-QG-LD128E(Q)I', '北京利达华信电子有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 解码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n\\tvar object = decodeStr(fox_edge_data, fox_edge_param);\\n  return JSON.stringify(object);\\n}\\n\\n/**\\n * 事件解码器函数：消火栓按钮报火警\\n * 全局参数：\\n *     fox_edge_data：hex string格式的接收数据\\n *                    XXX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   必须是列表格式的JSON字符串，并且JSON对象必须包含关键字【recordType】，否则不给与入库\\n */\\nfunction decodeStr(message, device_param) {\\n    var result = decodeType(message, \\"系统复位\\");\\n    return result;\\n}", "main": "decode"}}', '{"description": "报文格式：\\n以1B 40 1B 31 05 1B 36 1B 39开始，以0A 1B 4A 01 1B 39 字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1B 31 05 1B 36 1B 39 32 31 2F 30 34 2F 30 32 20 31 36 3A 33 34 3A 30 38 0A CF B5 CD B3 B8 B4 CE BB 0A 1B 4A 01 1B 39\\n\\n报文内容：\\n\\u001b@\\u001b1\\u0005\\u001b6\\u001b921/04/02 16:34:08\\n系统复位\\n\\u001bJ\\u0001\\u001b9"}', 'report', 'record', 1, 2000, 1727011620832, 1727011620832),
	(661, 'splitHandler', 'JB-QG-LD128E(Q)I', '北京利达华信电子有限公司', 'JavaScript', 'channel', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     message：hex string格式的接收数据\\n *              XX+[合法报文]+XXX，合法报文可能混杂在一堆其他数据之中\\n * 返回值：\\n *   从XXX+[合法报文]+XXX中，截取到的[合法报文]\\n */\\nfunction decode(message) {\\n    var starTag = \\"1B 40 1B 31 05 1B 36 1B 39\\";\\n    var endTag = \\"0A 1B 4A 01 1B 39\\";\\n\\n    message = message.replace(/\\\\s+/g, \\"\\");\\n    starTag = starTag.replace(/\\\\s+/g, \\"\\");\\n    endTag = endTag.replace(/\\\\s+/g, \\"\\");\\n\\n    // 转换成大写\\n    message = message.toUpperCase();\\n    starTag = starTag.toUpperCase();\\n    endTag = endTag.toUpperCase();\\n\\n    // 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找第一个结束标记\\n    var end = message.indexOf(endTag);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    while (true) {\\n        var line = getLine(message, starTag, endTag);\\n        if (line.length > 0) {\\n            return line;\\n        }\\n\\n        message = message.substring(endTag.length);\\n        if (message.length == 0) {\\n            return \\"\\";\\n        }\\n    }\\n\\n    return result;\\n}\\n\\nfunction getLine(message, starTag, endTag) {\\n// 寻找起始标记\\n    var start = message.indexOf(starTag);\\n    if (start < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找第一个结束标记\\n    var end = message.indexOf(endTag);\\n    if (end < 0) {\\n        return \\"\\";\\n    }\\n\\n    // 寻找后续多行\\n    var lines = message.substring(start, message.length);\\n    for (var i = 0; i < 8; i++) {\\n        var next = lines.indexOf(starTag, end + 2);\\n        var pos = lines.indexOf(endTag, end + 2);\\n\\n        // 检查：是否还有下一行，或者出现了实际上的下一行换行符\\n        if (pos < 0 || pos > next) {\\n            break;\\n        }\\n\\n        end = pos;\\n    }\\n\\n    if (start >= end) {\\n        return \\"\\";\\n    }\\n\\n    // 分拆数据\\n    var data = message.substring(start, end + endTag.length);\\n\\n\\n    // 截取数据\\n    var result = data;\\n\\n    return result;\\n}\\n", "main": "decode"}}', '{"description": "报文格式：\\n以1B 40 1B 31 05 1B 36 1B 39开始，以0A 1B 4A 01 1B 39 字符结束的多行文本\\n\\n--------------------------------------------------------------------------------------------------------------------------\\n\\n测试报文1：\\n1B 40 1B 31 05 1B 36 1B 39 32 31 2F 30 34 2F 30 32 20 31 36 3A 33 34 3A 30 38 0A CF B5 CD B3 B8 B4 CE BB 0A 1B 4A 01 1B 39\\n\\n报文内容：\\n\\u001b@\\u001b1\\u0005\\u001b6\\u001b921/04/02 16:34:08\\n系统复位\\n\\u001bJ\\u0001\\u001b9\\n"}', 'splitHandler', 'status', 1, 2000, 1727011620847, 1727011620847),
