	(715, '设置运行状态', '柜式空调(KPRd)', 'TCL科技集团股份有限公司', 'Java', 'device', '{}', '{}', 'exchange', 'status', 1, 4000, 1731396490894, 1731396490894),
	(716, 'writeData', 'S7 PLC', 'Siemens', 'Java', 'device', '{}', '{}', 'exchange', 'status', 1, 2000, 1731396490956, 1731396490956),
	(717, 'foxLibs', '机械臂', '睿尔曼智能科技有限公司', 'JavaScript', 'device', '{"include": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 数组的拷贝\\n *\\n * @param srcUint8Array\\n * @param srcPos\\n * @param dstUint8Array\\n * @param dstPos\\n * @param length\\n */\\nfunction arraycopy(srcUint8Array, srcPos, dstUint8Array, dstPos, length) {\\n    var src = srcPos;\\n    var dst = dstPos;\\n    for (var index = 0; index < length; index++, src++, dst++) {\\n        dstUint8Array[dst] = srcUint8Array[src];\\n    }\\n}\\n\\n/**\\n * 数组转换为hex\\n *\\n * @param uint8Array\\n * @returns {string}\\n */\\nfunction arrayToHex(uint8Array) {\\n    var hex = \\"\\";\\n    for (var i = 0; i < uint8Array.length; i++) {\\n        var ch = uint8Array[i].toString(16);\\n        hex += padStart(ch, 2, \'0\').toUpperCase();\\n    }\\n\\n    return hex;\\n}\\n\\n/**\\n * hex转数组\\n * @param hex\\n * @returns {Uint8Array}\\n */\\nfunction hexToArray(hex) {\\n    var hex = hex.replace(/\\\\s+/g, \\"\\").toUpperCase();\\n    var uint8Array = new Uint8Array(hex.length / 2);\\n    for (var i = 0; i < uint8Array.length; i++) {\\n        uint8Array[i] = parseInt(hex[2 * i] + hex[2 * i + 1], 16);\\n    }\\n\\n    return uint8Array;\\n}\\n\\n/**\\n * 将ASCII格式的文本，转换为HEX格式的文本\\n * 范例：asciiToHex(\\"ABC\\")，返回字符串 \\"414243\\"\\n *\\n * @param asciiString\\n * @returns {string}\\n */\\nfunction asciiToHex(asciiString) {\\n    var hexString = \'\';\\n    for (var i = 0; i < asciiString.length; i++) {\\n        var code = asciiString.charCodeAt(i);\\n        var hex = code.toString(16);\\n        hexString += padStart(hex,2,\\"0\\");\\n    }\\n    return hexString;\\n}\\n\\n/**\\n * 将HEX格式的字符串，还原会字符串\\n * 范例：hexToAscii(\\"414243\\")，返回字符串 \\"ABC\\"\\n *\\n * @param hexString\\n * @returns {string}\\n */\\nfunction hexToAscii(hexString) {\\n    var text = \\"\\";\\n    for (var i = 0; i < hexString.length; i += 2) {\\n        text += String.fromCharCode(parseInt(hexString[i] + hexString[i + 1], 16));\\n    }\\n\\n    return text;\\n}\\n\\n/**\\n * 替代JS旧版本不支持的padStart函数\\n *\\n * @param str\\n * @param length\\n * @param ch\\n * @returns {*}\\n */\\nfunction padStart(str, length, ch) {\\n    while (str.length < length) {\\n        str = ch + str;\\n    }\\n\\n    return str;\\n}\\n\\n/**\\n * CRC16校验\\n * 范例：var crc16 = calculateCRC16(data, 0, data.length - 2, 0xFFFF, 0xA001);\\n *\\n * @param bytes Uint8Array格式的数组\\n * @param offset 数组的偏移量\\n * @param length 需要计算的长度\\n * @param init CRC16的初始值，例如：0x0000\\n * @param poly CRC16的多项式，例如：0xA001\\n * @returns {number} CRC16\\n */\\nfunction calculateCRC16(bytes, offset, length, init, poly) {\\n    var crc = init;\\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\\n\\n    for (var i = offset; i < length; i++) {\\n        crc ^= bytes[i];\\n        for (var j = 0; j < 8; j++) {\\n            if (crc & 0x0001) {\\n                crc = ((crc >> 1) ^ polynomial) & 0xFFFF;\\n            } else {\\n                crc >>= 1;\\n            }\\n        }\\n    }\\n\\n    return crc & 0xffff\\n}\\n\\n/**\\n * IEEE754浮点数的转换\\n * 说明：32位浮点（数默认格式：低位在前，高位在后）\\n * 测试范例：45 0f 60 00 数值位2294.0\\n * bitsToFloat(0x00, 0x60, 0x0f, 0x45) = 2294.0\\n *\\n * @param bit3\\n * @param bit2\\n * @param bit1\\n * @param bit0\\n * @returns {number}\\n */\\nfunction bitsToFloat(bit3, bit2, bit1, bit0) {\\n    var bits = (bit0 << 24) | (bit1 << 16) | (bit2 << 8) | (bit3);\\n    var sign = ((bits >>> 31) == 0) ? 1.0 : -1.0;\\n    var e = ((bits >>> 23) & 0xff);\\n    var m = (e == 0) ? (bits & 0x7fffff) << 1 : (bits & 0x7fffff) | 0x800000;\\n    var f = sign * m * Math.pow(2, e - 150);\\n    return f;\\n}\\n\\n/**\\n * 判定是否存在Empty的参数\\n *\\n * @param arg\\n * @returns {boolean}\\n */\\nfunction testEmpty(arg, error) {\\n    if ((arg == undefined || arg == null || arg === \'\')) {\\n        throw Error(error);\\n    }\\n}\\n", "main": "include"}}', '{"description": "Fox-Edge提供的常用公共库JS函数。\\n\\n它的目的，是提供JS开发者们写解码器的时候，会用到的许多常用函数，避免不必要的重复性开发工作"}', 'include', 'status', 1, 2000, 1731596301911, 1731596301911),
	(718, '操作', '机械臂', '睿尔曼智能科技有限公司', 'JavaScript', 'device', '{"decode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction decode() {\\n    return decodeCommand(fox_edge_data, fox_edge_param);\\n}\\n\\n/**\\n * 开发者自己写的解码函数1\\n * 返回格式：JSON格式的字符串\\n */\\nfunction decodeCommand(message, param) {\\n    // 转换成文本\\n    var jsn = hexToAscii(message)\\n\\n    // 尝试解析为JSON对象\\n    var result = JSON.parse(jsn);\\n\\n    // 重新转换为JSON字符串\\n    return JSON.stringify(result);\\n}\\n\\n", "main": "decode"}, "encode": {"code": "/* ----------------------------------------------------------------------------\\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-2020. All rights reserved.\\n *\\n *     This program is free software: you can redistribute it and/or modify\\n * it under the terms of the GNU General Public License as published by\\n * the Free Software Foundation, either version 3 of the License, or\\n * (at your option) any later version.\\n *\\n *     This program is distributed in the hope that it will be useful,\\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\\n * GNU General Public License for more details.\\n *\\n *     You should have received a copy of the GNU General Public License\\n * along with this program.  If not, see <https://www.gnu.org/licenses/>.\\n * --------------------------------------------------------------------------- */\\n\\n/**\\n * 编码器的入口函数\\n * 全局参数：\\n *     fox_edge_param：json string格式的设备参数的合并对象\\n * 返回值：\\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\\n */\\nfunction encode() {\\n    return encodeCommand(fox_edge_param);\\n}\\n\\n/**\\n * 数据编码\\n *\\n * @param param\\n * @returns {string}\\n */\\nfunction encodeCommand(param) {\\n    // 将参数转成JSON字符串\\n    var jsn = JSON.stringify(param)\\n\\n    // 按机械臂厂商的要求，增加\\\\r\\\\n作为提交\\n    jsn += \\"\\\\r\\\\n\\"\\n\\n    return asciiToHex(jsn);\\n}", "main": "encode"}}', '{"description": ""}', 'exchange', 'result', 1, 2000, 1731596311664, 1731596311664);
